export default [{"id":703,"question":"مجموعة أسئلة تدور حول طلب بيان: أين يضع المُصلي يديه في القيام؟ وذلك لأنه يقول: لاحظ الاختلاف: إما على السرة، أو على الصدر، أو بعضهم لا يرفعها، وإنما يتركها مُسدلةً، فما الوجه الصَّحيح؟","title":"أين يضع المصلي يديه في القيام بالصلاة؟","answer":"الجواب: العلماء في هذا اختلفوا: فمنهم مَن أرسلها عن جانبيه، ومنهم مَن وضعها على السرة، ومنهم مَن يضعها تحت السرة، ومنهم مَن يضعها على الصدر، وأرجح الأقوال وضعها على الصدر، هذا أرجح الأقوال.\nومَن صلَّى سادلًا أو جعلها على سُرته أو تحتها فالأمر سهلٌ في ذلك، صلاته صحيحة، لكن السنة أن يضعهما على الصدر؛ لما ثبت عن الرسول ﷺ في ذلك، فقد جاء من حديث وائل بن حجر: أنَّ النبي ﷺ كان يضع يديه على صدره في الصلاة، وجاء أيضًا من حديث قبيصة بن هلب، عن أبيه: أنه رأى النبيَّ وضع يده على صدره في الصلاة، وإسنادهما جيد، يشدُّ أحدُهما الآخر، وإسنادهما قويٌّ.\nوثبت عن طاووس بن كيسان اليماني التابعي الجليل مرسلًا عن النبي ﷺ أنه كان يضع يديه على صدره، وهذا يتأيَّد بالحديثين السَّابقين.\nوفي \"صحيح البخاري\" رحمه الله: عن سهل بن سعدٍ رضي الله تعالى عنهما قال: \"كان الرجلُ يُؤمر أن يضع يده اليمنى على ذراعه اليسرى في الصلاة\"، قال أبو حازم الراوي عن سهل: ولا أعلمه إلا ينمي ذلك إلى النبي ﷺ. وهو أصحُّ ما ورد في ذلك، ويدل على وقوع اليُمنى على اليُسرى على الكفِّ والرسغ والساعد، وحديث وائل وما جاء في معناه يُبين محلّه، وأنه على صدره.\nوإذا وضعه على ذراعه فهو سنة، وقد جاء من الحديثين أنَّ وضعها على الكفِّ والرسغ والساعد، تكون أطرافه على الذراع، فلا منافاة، يعني: وضع كفَّه اليمنى على كفِّه اليسرى ووصل الساعد، صارت الأطراف في كفِّه اليمنى على ذراعه اليسرى، فتجتمع الأحاديث كلها في وضع اليمين على الشمال على الصَّدر، والأحاديث يُفسِّر بعضُها بعضًا.\nوأما وضعها على السرة أو تحت السرة فالخبر فيها ضعيفٌ، وأما إرسالها عن جانبيه وإسدالها عن جانبيه فهو مكروهٌ، لا دليلَ عليه.\nس: الإسدال مكروهٌ؟\nج: لا دليلَ عليه: طرحها على جانبيه.\nس: إنما الأوْلى أن يرفعها؟\nج: إما هكذا وهو الأفضل، أو على السرة، أو تحت السرة، هذه الأقوال الثلاثة التي جاءت فيها بعض النصوص، لكن أصحّها هكذا: يضعها على صدره.","link":"https://binbaz.org.sa/fatwas/20534/اين-يضع-المصلي-يديه-في-القيام-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0502فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["سنن الصلاة"]},{"id":1983,"question":"وضع اليد على النّحر، أو على الجهة اليسرى -جهة القلب- أثناء القيام؟","title":"ما صفة وضع اليدين في القيام بالصلاة؟","answer":"الجواب:\nلا، السُّنة أن تُوضَع اليُمنى على اليُسرى على صدره، كما جاء في حديث وائل بن حُجر، وحديث هُلب الطائي.","link":"https://binbaz.org.sa/fatwas/22099/ما-صفة-وضع-اليدين-في-القيام-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صفة وضع اليدين في القيام للصلاة.mp3","categories":["سنن الصلاة"]},{"id":2356,"question":"إذا رفع المُصلي يديه، ثم أرسلها، ثم وضعها على صدره، هل صحَّت في ذلك أحاديث؟","title":"ما كيفية رفع ووضع اليدين في الصلاة؟","answer":"الجواب:\nالسنة أن يرفع يديه عند الإحرام، ثم يضعها على صدره، هذه هي السنة، ما يحتاج إلى إرسالها.\nس: بعض المُصلين يُرسلها ثم يضعها على صدره؟\nج: لا، يُعَلَّم أن يضعها على صدره بعدما يُكبِّر.","link":"https://binbaz.org.sa/fatwas/22481/ما-كيفية-رفع-ووضع-اليدين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رفع المُصلي يديه ثم إرسالهما ثم وضعهما على الصدر.mp3","categories":["سنن الصلاة"]},{"id":3234,"question":"التَّعَوُّذ من الشيطان في كل ركعة؟","title":"هل يُشرع التَّعَوُّذ من الشيطان في كل ركعة؟","answer":"الجواب: الراجح في أولها، والباقي التسمية تكفي إن قرأ سورة. وإن تعوذ زود خير إن شاء الله؛ لأن قراءة الصلاة كالشيء الواحد.","link":"https://binbaz.org.sa/fatwas/23397/هل-يشرع-التعوذ-من-الشيطان-في-كل-ركعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التعوذ من الشيطان في كل ركعة.mp3","categories":["سنن الصلاة"]},{"id":3526,"question":"الذي يقول بأن الاستراحة خاصة بالرسول ﷺ لما كَبُر؟","title":"هل جلسة الاستراحة خاصة بالرسول ﷺ لما كبر؟","answer":"الجواب: لا، من صفة الصلاة، الصواب: أنها من صفة الصلاة.\nس: للصغير والكبير؟\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/23707/هل-جلسة-الاستراحة-خاصة-بالرسول-ﷺ-لما-كبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم جلسة الاستراحة.mp3","categories":["سنن الصلاة"]},{"id":3569,"question":"من قال إن رفع اليدين يكون بين الأذنين والمنكبين، هل له وجه؟","title":"صفة رفع اليدين في الصلاة","answer":"الجواب: تارة حذاء منكبيه، وتارة حيال أذنيه.","link":"https://binbaz.org.sa/fatwas/23751/صفة-رفع-اليدين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صفة رفع اليدين في الصلاة.mp3","categories":["سنن الصلاة"]},{"id":3579,"question":"عدم رفع اليد مع التكبير ؟","title":"حكم رفع اليدين عند التكبير في الصلاة","answer":"الجواب: رفع اليد ما هو مشروع إلا في التكبيرة الأولى، والركوع، والرفع منه، وعند القيام من التشهد الأول إلى الثالثة يرفع يديه، أفضل، مستحب وليس بواجب.","link":"https://binbaz.org.sa/fatwas/23761/حكم-رفع-اليدين-عند-التكبير-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم رفع اليدين عند التكبير.mp3","categories":["سنن الصلاة"]},{"id":4563,"question":"يلزم من التَّكبيرات رفع اليدين؟","title":"ما مواضع رفع اليدين في تكبيرات الصلاة؟","answer":"الجواب: عند الإحرام، والركوع، والرفع منه، وعند القيام من التشهد الأول، في المواضع الأربعة.","link":"https://binbaz.org.sa/fatwas/24845/ما-مواضع-رفع-اليدين-في-تكبيرات-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رفع اليدين في الصلاة عند التكبيرات.mp3","categories":["سنن الصلاة"]},{"id":4570,"question":"بالنسبة لقضية التَّورك: ذهب بعضُ أهل العلم إلى أنه يُدخل قدمَه بين ساقه وفخذه؟","title":"ما الصفة الصحيحة للتورك في الصلاة؟","answer":"الجواب: تقدم الكلام على هذا؛ أن رواية ابن الزبير فيها نظر، والظاهر أنها وهم من بعض الرواة، والمعروف من عمل النبي ﷺ أنه الافتراش، وأن التورك يُخرج رجلَه من جهة اليمين تحت فخذه وساقه، أما إدخالها بين الفخذ والساق فهذا فيه صعوبة ومشقة، وأيضًا عدم خشوع في الصلاة، فلعل بعض الرواة وهم أنه يُدخلها تحت فخذه وساقه، فجعلها بين فخذه وساقه، وإنما الصواب جعلها تحت فخذه وساقه، والأحاديث المشتبهة تُفسَّر بالأحاديث الواضحة.","link":"https://binbaz.org.sa/fatwas/24853/ما-الصفة-الصحيحة-للتورك-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التورك وصفته.mp3","categories":["سنن الصلاة"]},{"id":5088,"question":"سؤاله الثاني يقول: أين يضع المصلون أيديهم بعد الركوع؟","title":"أين يضع المصلي يديه بعد الركوع؟","answer":"الجواب: السنة أن توضع الأيدي على الصدر، قبل الركوع وبعده، قال النبي ﷺ في الحديث الصحيح، فيما روى مسلم في صحيحه عن وائل قال: كان النبي ﷺ يضع يده اليمنى على كفه اليُسرى. وقال سهل بن سعد : \"كان الرجل يؤمر أن يضع يده اليمنى على ذراعه اليسرى في الصلاة\". وفي مسند أحمد وغيره عن أحد الصحابة: \"أنه رأى النبي ﷺ وضع يديه على صدره في الصلاة\". وقال وائل: \"رأيت النبي ﷺ يضع يديه على صدره في الصلاة\". فهذه هي السنة؛ أن يضعهما على صدره وهو قائم في الصلاة، قبل الركوع وبعده، لا فرق في ذلك؛ لأن وائلاً قال: \"رأيت النبي ﷺ إذا كان قائماً في الصلاة وضع يمينه على شماله على صدره في الصلاة\".","link":"https://binbaz.org.sa/fatwas/29991/اين-يضع-المصلي-يديه-بعد-الركوع","audio":"undefined","categories":["سنن الصلاة"]},{"id":5538,"question":"الصلاة في النعال يقال له: سُنة أو جائزة؟","title":"هل الصلاة في النعال سنة؟","answer":"الجواب: سُنة، مستحب، النبي ﷺ قال: خالفوهم إنَّ اليهود لا يُصلون في نعالهم فخالفوهم، وكان يُصلي في نعليه إلا في الأحوال القليلة كان يفسخها؛ ليُبين الجواز، ليبين أنه ليس بلازمٍ؛ ولهذا في الغالب يُصلي في نعليه، وفي بعض الأحيان يخلعهما ويُصلي حافيًا عليه الصلاة والسلام؛ للدلالة على أنه جائز، وليس بلازمٍ. ولكن الآن بعدما كانت المساجدُ مفروشةً بالفرش قد يتساهل الناسُ؛ لأنَّ أكثر الخلق لا يعتني بالنَّعلين عند دخول المسجد، لا يُبالي، فربما دخل فيهما أذى، أو طين، أو أوساخ أخرى، فيُوسخ على الناس فرشهم، ويُقذر عليهم موضع سجودهم، فإذا جعلها في مكانٍ عند باب المسجد، أو في مكانٍ آخر؛ حتى لا يُؤذي الناس؛ فهذا حسنٌ إن شاء الله، لا زهدًا في السنة، ولكن لأجل ما هو معروف من العامَّة، والغالب أنهم لا يعتنون بالنِّعال.[1]","link":"https://binbaz.org.sa/fatwas/31474/هل-الصلاة-في-النعال-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 002.mp3","categories":["سنن الصلاة"]},{"id":5703,"question":"الصلاة في النعال؟","title":"مشروعية الصلاة بالنعال","answer":"الجواب:  سنة وقربة وطاعة إذا كانت نظيفة سليمة، ولكن لما جاءت المفارش هذه، وصار الناس يدوسونها، ويقذرونها على الناس، وأكثر الناس لا يبالي بنعليه، ولا يعتني بها، فيحملها، ويجعلها في مكان خاص حتى لا يقذر الفرش على الناس؛ لأن أكثر الناس لا يبالون، ولا يعتنون بالنعال، وليس عندهم بصيرة بهذا، ولما كانت المساجد الأولى حصباء، ورمل ما يضرها ذلك.  والواجب دائمًا ألا يدخل المسجد إلا بعناية، وينظر نعليه عند دخول المسجد حتى لا يكون فيها قذر تقذر المسجد، ولو كان بطحاء، ولو كان المسجد حصباء، ليس له دخول المسجد إلا بعد النظر في نعليه، وقلبها حتى يزيل ما بها من أذى، ثم يصلي بها لا بأس، كما صلى بها النبي ﷺ. لكن اليوم بعدما فرشت المساجد، وصار فيها فرش ثمينة، وأقل شيء يؤثر فيها، وربما نفر الناس من الصلاة عليها، وأداء الجماعة، فينبغي للمؤمن ألا ينفر الناس، بل يكون عونًا لهم على أداء الجماعة، ويحفظ نعليه في مكان آخر.","link":"https://binbaz.org.sa/fatwas/1009/مشروعية-الصلاة-بالنعال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_35.mp3","categories":["التكبير والاستفتاح","سنن الصلاة"]},{"id":5709,"question":"الصلاة في النعال؟","title":"مشروعية الصلاة بالنعال","answer":"الجواب:  سنة وقربة وطاعة إذا كانت نظيفة سليمة، ولكن لما جاءت المفارش هذه، وصار الناس يدوسونها، ويقذرونها على الناس، وأكثر الناس لا يبالي بنعليه، ولا يعتني بها، فيحملها، ويجعلها في مكان خاص حتى لا يقذر الفرش على الناس؛ لأن أكثر الناس لا يبالون، ولا يعتنون بالنعال، وليس عندهم بصيرة بهذا، ولما كانت المساجد الأولى حصباء، ورمل ما يضرها ذلك.  والواجب دائمًا ألا يدخل المسجد إلا بعناية، وينظر نعليه عند دخول المسجد حتى لا يكون فيها قذر تقذر المسجد، ولو كان بطحاء، ولو كان المسجد حصباء، ليس له دخول المسجد إلا بعد النظر في نعليه، وقلبها حتى يزيل ما بها من أذى، ثم يصلي بها لا بأس، كما صلى بها النبي ﷺ. لكن اليوم بعدما فرشت المساجد، وصار فيها فرش ثمينة، وأقل شيء يؤثر فيها، وربما نفر الناس من الصلاة عليها، وأداء الجماعة، فينبغي للمؤمن ألا ينفر الناس، بل يكون عونًا لهم على أداء الجماعة، ويحفظ نعليه في مكان آخر.","link":"https://binbaz.org.sa/fatwas/1009/مشروعية-الصلاة-بالنعال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_35.mp3","categories":["التكبير والاستفتاح","سنن الصلاة"]},{"id":5829,"question":"هل يجب دعاء الاستفتاح عند الصلاة على الميت؟","title":"حكم دعاء الاستفتاح في صلاة الجنازة","answer":"الجواب: أما الصلاة على الميت فهي مخففة، فذكر العلماء أنه لا يستفتح فيها يبدأ بالتعوذ، والبسملة، ويقرأ الفاتحة، ولا يحتاج إلى استفتاح؛ لأنها صلاة مخففة، يطلب فيها تعجيل الميت، والإسراع به؛ فالأفضل أن لا يكون هناك استفتاح، هذا هو المنصوص عند أهل العلم. وبعض أهل العلم يرى فيها استفتاح، ولكن الأقرب -والله أعلم- عدم ذلك؛ لأنها صلاة مخففة، ليست ذات ركوع، ولا سجود.","link":"https://binbaz.org.sa/fatwas/1159/حكم-دعاء-الاستفتاح-في-صلاة-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_158.mp3","categories":["التكبير والاستفتاح","سنن الصلاة"]},{"id":6035,"question":"ما حكم قراءة دعاء الاستفتاح في السنن الراتبة؟ وهل هو مستحب؟","title":"حكم دعاء الاستفتاح في صلاة النافلة","answer":"الجواب: مستحب الدعاء، مستحب في السنن، والفرائض.","link":"https://binbaz.org.sa/fatwas/1431/حكم-دعاء-الاستفتاح-في-صلاة-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_369.mp3","categories":["سنن الصلاة","التكبير والاستفتاح"]},{"id":6667,"question":"هل يجوز إذا قال في الاستفتاح: وجهت وجهي للذي فطر السماوات، والأرض إلى آخر الآيات؟","title":"تنوع أدعية الاستفتاح في الصلاة","answer":"الجواب: كل ما صح عن النبي ﷺ يجوز، كل الاستفتاحات في الصلاة الثابتة عن النبي ﷺ يستفتح بها، بعد التحريمة بعد قوله: الله أكبر التكبيرة الأولى يستفتح، كل ما صح عن النبي ﷺ إذا قال: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك، وإذا دعا: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج، والماء، والبرد، ومنها وجهت وجهي للذي فطر السماوات، والأرض حنيفًا، وما أنا من المشركين، إلى آخره، ومنها أشياء أخرى. السؤال: ويقول: وأنا أول المسلمين؟ الجواب: وأنا من المسلمين.. الأول النبي ﷺ، أما أنت فمن المسلمين.","link":"https://binbaz.org.sa/fatwas/2552/تنوع-ادعية-الاستفتاح-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1047.mp3","categories":["التكبير والاستفتاح","سنن الصلاة"]},{"id":7029,"question":"إذا نسي الإنسان تكبيرة الإحرام، فهل يستمر  في الصلاة حتى ينتهي، ثم يعيدها، أو يقطعها، ثم يعيدها؟","title":"حكم من نسي تكبيرة الإحرام وتذكر أثناء الصلاة","answer":"الجواب:\n\nإذا شك هل كبر، أو ما كبر، يكبر في الحال، ويعمل لما أدرك بعد التكبير، إذا أعاد التكبيرة في الثانية من صلاة الإمام؛ اعتبر نفسه فاتته الأولى.\n\nوإذا أعاد التكبير في الثالثة اعتبر نفسه فاتته ركعتان، فيقضي ركعتين بعد الصلاة، هذا إذا كان ما هو موسوس، أما إذا كان موسوسًا -عنده وساوس- فلا يلتفت إلى هذا، يبني على ما تقدم ويعرف أنه كبر، والحمد لله.","link":"https://binbaz.org.sa/fatwas/3004/حكم-من-نسي-تكبيرة-الاحرام-وتذكر-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1412.mp3","categories":["التكبير والاستفتاح","سنن الصلاة"]},{"id":7786,"question":"يقول أيضاً: هل وضع اليد اليمنى على اليسرى على الصدر بعد الرفع من الركوع سنة أو بدعة؟ وما الدليل؟","title":"حكم وضع اليد اليمنى على اليسرى بعد الركوع","answer":"الجواب: وضع الأيدي على الصدر قبل الركوع وبعده سنة، والدليل على ذلك: أن النبي ﷺ: كان يضع يده اليمنى على اليسرى في الصلاة وكان يأمر بذلك، وقد ثبت في الصحيح من حديث وائل أن النبي ﷺ: كان يضع يده اليمنى على كفه اليسرى وجاء في الروايات الأخرى: والرسغ والساعد فهذا هو السنة، وجاء في رواية وائل بن حجر عند ابن خزيمة: أنه يضعهما على صدره وكذا عند أحمد من حديث قبيصة بن هلب الطائي عن أبيه: أن النبي ﷺ كان يضع يديه على صدره حال كونه قائمًا في الصلاة وهكذا قال وائل: كان النبي ﷺ إذا كان قائمًا في الصلاة وضع يمينه على شماله فدل ذلك على أنه في حال قيامه يضعهما على صدره سواء كان القيام قبل الركوع أو بعد الركوع، وهكذا جاء من حديث طاوس مرسلاً عن النبي ﷺ بإسناد جيد وضع اليمين على الشمال على الصدر، هذا هو أصح ما قيل في هذا، وضعهما على الصدر قبل الركوع وبعده.  أما ما وقع في رسالة بعض إخواننا الذين صنفوا صلاة النبي ﷺ من زعمه أن وضعهما على الصدر بعد الركوع بدعة، فهو خطأ غلط، غلط ممن قال ذلك، فلا ينبغي أن يعول عليه، ولا ينبغي أن يكون ذلك مانعًا من الاستفادة من كتبه وما فيها من الفوائد، لكن هذا الخطأ؛ كل يخطي ويغلط، فقول من كتب في صفة صلاة النبي ﷺ أن وضعهما على الصدر بعد الركوع بدعة قول غلط، وهو قول أخينا في الله الشيخ: ناصر الدين الألباني، قد غلط في هذا، وهو علامة جليل مفيد، وكتبه مفيدة، لكن كُلٌّ يغلط، وله أغلاط معدودة، نسأل الله أن يوفقه للرجوع عنها. نعم.","link":"https://binbaz.org.sa/fatwas/5128/حكم-وضع-اليد-اليمنى-على-اليسرى-بعد-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_048/04807.mp3","categories":["سنن الصلاة"]},{"id":8005,"question":"أيضاً لدى فؤاد محمد أحمد علي سؤال آخر يقول: عرفونا عن آية من سورة الفاتحة وهي آمين، الذي تأتي بعد: وَلا الضَّالِّينَ [الفاتحة:7] فهل هي آية أم سنة أم مستحبة؟","title":"حكم قول: (آمين) بعد الفاتحة","answer":"الجواب: أيها السائل! قول (آمين) بعد الفاتحة ليست من آيات القرآن، وليست من آيات الفاتحة، وإنما هي دعاء بمعنى: استجب يا ربنا، فـ (آمين) معناها: اللهم استجب، فهي سنة وليست واجبة بل سنة بعد الفاتحة يقولها القاري في الصلاة وغيرها، يقول: (آمين) إذا قرأ الفاتحة، يقولها الإمام.. يقولها المأموم.. يقولها المنفرد في الصلاة وخارجها، آمين، هذه السنة، ليست واجبة ولكنها مستحبة، وهي دعاء وليست آية من الفاتحة ولا من غيرها، وإنما هي دعاء. نعم.","link":"https://binbaz.org.sa/fatwas/5571/حكم-قول-امين-بعد-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_075/07504.mp3","categories":["سنن الصلاة"]},{"id":8013,"question":"هذه الرسالة وردتنا من أحد السادة المستمعين لم يوضح اسمه يسأل عن وضع اليدين في الصلاة، يقول: في الصلاة أن سنة النبي ﷺ يضع يده اليمنى على اليسرى واختلفت الأقوال في ذلك، نريد الوقوف على القول الصحيح؟","title":"كيفية الضم في الصلاة وحكمه","answer":"الجواب: السنة أن يضع يمينه على شماله في الصلاة حال وقوفه في الصلاة قبل الركوع وبعده، يضع يده اليمنى على كفه اليسرى والرسغ والساعد، هذه السنة، واختلف أهل العلم في محلها فقيل: على صدره، وقيل: على سرته، وقيل: تحت سرته، ويروى في هذا أحاديث عن النبي عليه الصلاة والسلام، لكن أصحها وأثبتها على صدره، أصح ما ورد على صدره، هذا هو أصح ما ورد عن وائل بن حجر ، وعن قبيصة بن هلب الطائي عن أبيه، وعن طاوس مرسلا، كلها تدل على أن السنة وضع اليدين على الصدر، اليمنى على اليسرى على الصدر، هذا هو الأفضل والأمر في هذا واسع إن شاء الله، ولكن تحري السنة هو الذي ينبغي، أما حديث وضعها تحت السرة فهو ضعيف، والأرجح منه والأصح وضعهما على الصدر، يعني: على مقدم الصدر لا يبالغ بل إذا وضعها على مقدم الصدر كفى. والحاصل أن هذا هو الأفضل وهو الأرجح. نعم..\nالمقدم: يقول في رسالته أيضاً: إذا كان الإمام لا يضع يده اليمنى على اليسرى بل يسبلهما، هل يقتدي المأموم به أم يخالفه ويضع يده اليمنى على اليسرى؟\nالشيخ: إذا أرسل يديه الإمام فقد خالف السنة فلا يقتدى به، بل المأموم يضع يده اليمنى على اليسرى حتى يفعل السنة ولا يقتدي بالإمام في خلاف السنة، وهكذا إذا كان الإمام لا يرفع عند الركوع أو عند الرفع منه أو عند القيام إلى الثالثة فإن المأموم يرفع؛ لأن الرسول كان يرفع عليه الصلاة والسلام عند الإحرام، ويرفع عند الركوع وعند الرفع منه، وعند القيام إلى الثالثة، فالرسول ﷺ هو المقتدى به هو الإمام عليه الصلاة والسلام، هو الإمام الأعظم فهو المقتدى به عليه الصلاة والسلام، فإذا قصر إمامك ولم يأت بالسنة فأنت لا تقتدي به بخلاف السنة، بل تأتي بالسنة وإن خالفت الإمام فقد وافقت الإمام الأعظم رسول الله عليه الصلاة والسلام. نعم..\nالمقدم: بعض الناس يضع يده اليمنى على اليسرى لكنه يزيحها إلى جهة اليسار ويضعها على القلب ويخرج مرفقه الأيسر كثيراً، ما ... ؟\nالشيخ: ما ... لهذا أصل. أقول: لا أعلم لهذا أصلاً، وإنما السنة أن يضع يده على كفه اليسرى والرسغ والساعد ويضعهما على صدره هذه السنة، وإن وضع يده اليمنى على ذراعه اليسرى فلا بأس به؛ جاء به حديث سهل بن سعد ، فإن مد اليد إلى الذراع فلا بأس، وإن جعلها على الرسغ والساعد وصار أطرافها على الساعد فهذا هو الأفضل، وإن جعلها على الذراع فهو سنة أيضاً، ... ثبت عنه ﷺ أنه كان يضع يده اليمنى على كفه اليسرى والرسغ والساعد وثبت في حديث سهل قال: كان الرجل يؤمر أن يضع يده اليمنى على ذراعه اليسرى في الصلاة قال أبو حازم عن سهل: لا أعلمه إلا ينمي ذلك إلى النبي ﷺ، رواه البخاري . نعم..\nالمقدم: شكراً أثابكم الله.","link":"https://binbaz.org.sa/fatwas/5582/كيفية-الضم-في-الصلاة-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_076/07609.mp3","categories":["سنن الصلاة"]},{"id":8015,"question":"هذه الرسالة وردتنا من أحد السادة المستمعين لم يوضح اسمه يسأل عن وضع اليدين في الصلاة، يقول: في الصلاة أن سنة النبي ﷺ يضع يده اليمنى على اليسرى واختلفت الأقوال في ذلك، نريد الوقوف على القول الصحيح؟","title":"كيفية الضم في الصلاة وحكمه","answer":"الجواب: السنة أن يضع يمينه على شماله في الصلاة حال وقوفه في الصلاة قبل الركوع وبعده، يضع يده اليمنى على كفه اليسرى والرسغ والساعد، هذه السنة، واختلف أهل العلم في محلها فقيل: على صدره، وقيل: على سرته، وقيل: تحت سرته، ويروى في هذا أحاديث عن النبي عليه الصلاة والسلام، لكن أصحها وأثبتها على صدره، أصح ما ورد على صدره، هذا هو أصح ما ورد عن وائل بن حجر ، وعن قبيصة بن هلب الطائي عن أبيه، وعن طاوس مرسلا، كلها تدل على أن السنة وضع اليدين على الصدر، اليمنى على اليسرى على الصدر، هذا هو الأفضل والأمر في هذا واسع إن شاء الله، ولكن تحري السنة هو الذي ينبغي، أما حديث وضعها تحت السرة فهو ضعيف، والأرجح منه والأصح وضعهما على الصدر، يعني: على مقدم الصدر لا يبالغ بل إذا وضعها على مقدم الصدر كفى. والحاصل أن هذا هو الأفضل وهو الأرجح. نعم..\nالمقدم: يقول في رسالته أيضاً: إذا كان الإمام لا يضع يده اليمنى على اليسرى بل يسبلهما، هل يقتدي المأموم به أم يخالفه ويضع يده اليمنى على اليسرى؟\nالشيخ: إذا أرسل يديه الإمام فقد خالف السنة فلا يقتدى به، بل المأموم يضع يده اليمنى على اليسرى حتى يفعل السنة ولا يقتدي بالإمام في خلاف السنة، وهكذا إذا كان الإمام لا يرفع عند الركوع أو عند الرفع منه أو عند القيام إلى الثالثة فإن المأموم يرفع؛ لأن الرسول كان يرفع عليه الصلاة والسلام عند الإحرام، ويرفع عند الركوع وعند الرفع منه، وعند القيام إلى الثالثة، فالرسول ﷺ هو المقتدى به هو الإمام عليه الصلاة والسلام، هو الإمام الأعظم فهو المقتدى به عليه الصلاة والسلام، فإذا قصر إمامك ولم يأت بالسنة فأنت لا تقتدي به بخلاف السنة، بل تأتي بالسنة وإن خالفت الإمام فقد وافقت الإمام الأعظم رسول الله عليه الصلاة والسلام. نعم..\nالمقدم: بعض الناس يضع يده اليمنى على اليسرى لكنه يزيحها إلى جهة اليسار ويضعها على القلب ويخرج مرفقه الأيسر كثيراً، ما ... ؟\nالشيخ: ما ... لهذا أصل. أقول: لا أعلم لهذا أصلاً، وإنما السنة أن يضع يده على كفه اليسرى والرسغ والساعد ويضعهما على صدره هذه السنة، وإن وضع يده اليمنى على ذراعه اليسرى فلا بأس به؛ جاء به حديث سهل بن سعد ، فإن مد اليد إلى الذراع فلا بأس، وإن جعلها على الرسغ والساعد وصار أطرافها على الساعد فهذا هو الأفضل، وإن جعلها على الذراع فهو سنة أيضاً، ... ثبت عنه ﷺ أنه كان يضع يده اليمنى على كفه اليسرى والرسغ والساعد وثبت في حديث سهل قال: كان الرجل يؤمر أن يضع يده اليمنى على ذراعه اليسرى في الصلاة قال أبو حازم عن سهل: لا أعلمه إلا ينمي ذلك إلى النبي ﷺ، رواه البخاري . نعم..\nالمقدم: شكراً أثابكم الله.","link":"https://binbaz.org.sa/fatwas/5582/كيفية-الضم-في-الصلاة-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_076/07609.mp3","categories":["سنن الصلاة"]},{"id":8370,"question":"سماحة الشيخ! ذكرتم جلسة الاستراحة، حبذا لو فصلتم مكانها سماحة الشيخ، ومشروعيتها؟","title":"مشروعية جلسة الاستراحة ومكانها","answer":"الجواب: جلسة الاستراحة هي: جلسة خفيفة بعد الأولى من الصلوات الخمس، وبعد الثالثة في الرباعية، الظهر والعصر والعشاء، كان الرسول يفعلها عليه الصلاة والسلام، كما ثبت ذلك في حديث مالك بن الحويرث وفي حديث أبي حميد الساعدي . واختلف العلماء في ذلك، فمنهم من جعلها سنةً دائمةً في الصلاة، ومنهم من جعلها سنةً في حق المريض، وكبير السن، وحملوا الأحاديث الواردة في ذلك على هذا المعنى، والأرجح والأصوب أنها سنة مطلقاً، لأن الثابت عن النبي ﷺ أنه كان يفعلها، فهي سنة، لكنها جلسة خفيفة، مثل: الجلسة بين السجدتين، ليس فيها ذكر ولا دعاء، بل جلسة خفيفة ثم ينهض. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6219/مشروعية-جلسة-الاستراحة-ومكانها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11410.mp3","categories":["سنن الصلاة"]},{"id":8597,"question":"من أدرك الإمام راكعاً فهل تلزمه تكبيرة، أو تكبيرتان: تكبيرة الإحرام وتكبيرة الركوع؟","title":"حكم تكبيرة الانتقال لمن أدرك الإمام راكعاً","answer":"الجواب: نعم، إذا أدرك الإمام راكعاً فإنه يكبر أولاً وهو واقف تكبيرة الإحرام ثم يكبر حين ينحني للركوع، هذا هو الذي ينبغي وهذا هو الأصل، الأصل أن يكبر تكبيرتين الأولى: وهي تكبيرة الإحرام وهي فرض عند الجميع لا بد منها، والثانية فرض عند بعض أهل العلم وهي تكبيرة الركوع، وذهب الأكثرون إلى أنها سنة، ولكن ذهب الإمام أحمد رحمه الله وجماعة من السلف والخلف إلى أنها فريضة؛ لأن النبي ﷺ كبر وأمر بالتكبير وقال: صلوا كما رأيتموني أصلي في الركوع والسجود فدل ذلك على وجوب التكبيرات تكبيرات النقل تأسياً به ﷺ وتنفيذاً لأمره.\nأما تكبيرة الإحرام وهي الأولى، فهذه فريضة عند الجميع، لا يدخل الصلاة إلا بها، لو دخل في الصلاة بالنية ولم يكبر لم تنعقد صلاته، فلا بد من التكبير في أول الصلاة، وهي التكبيرة التي يقال لها: تكبيرة الإحرام، وهي المذكورة في قوله ﷺ: مفتاح الصلاة الطهور، وتحريمها التكبير، وتحليلها التسليم يعني: التكبير الأول.\nلكن إذا جاء والإمام راكع فقد يضيق الوقت فإن ترك تكبيرة الركوع صح عند جمع من أهل العلم، لضيق الوقت، ولكن إذا أتى بهما فهو الأحوط وفيه خروج من الخلاف، فينبغي له أن يأتي بهما على الأصل، يكبر وهو واقف التكبيرة الأولى وهي تكبيرة الإحرام ثم يكبر الثانية عند انحنائه وانخفاضه للركوع، متى تيسر ذلك فهذا هو الأحوط والأولى، ومتى ترك الثانية للضيق أجزأته الركعة والحمد لله في أصح قولي أهل العلم. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/6712/حكم-تكبيرة-الانتقال-لمن-ادرك-الامام-راكعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_129/12902.mp3","categories":["سنن الصلاة","التكبير والاستفتاح"]},{"id":8658,"question":"وهذه رسالة وردتنا من أحد الإخوة لم يذكر اسماً ولا عنواناً وهي رسالة طويلة لعلنا نتمكن من عرض بعض أسئلتها في هذه الحلقة والبقية في حلقات قادمة، يقول: هل يجوز رفع اليدين عند تكبيرة الإحرام فقط أم لابد من رفعها في جميع أركان الصلاة؟","title":"حكم من يرفع اليدين عند تكبيرة الإحرام فقط؟","answer":"الجواب: السنة: رفع اليدين عند الإحرام، وعند الركوع، وعند الرفع منه، وعند القيام من التشهد الأول إلى الثالثة، وليس ذلك واجباً بل هو سنة فعله المصطفى صلى الله عليه وسلم وفعله خلفاؤه الراشدون، وهو المنقول عن أصحاب النبي ﷺ، فالسنة للمؤمن أن يفعل ذلك في جميع الصلوات وهكذا المؤمنة؛ لأن الأصل أن الرجال والنساء سواء في الأحكام إلا ما خصه الدليل، فالسنة أن يرفع يديه عند التكبيرة الأولى حيال منكبيه أو حيال أذنيه، وهكذا عند الركوع، وهكذا عند الرفع منه، وهكذا عند القيام من التشهد الأول إلى الثالثة كما جاءت به الأخبار الصحيحة عن رسول الله عليه الصلاة والسلام، وذلك مستحب وسنة وليس بواجب، ولو صلى ولم يرفع صحت صلاته. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6797/حكم-من-يرفع-اليدين-عند-تكبيرة-الاحرام-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21402.mp3","categories":["سنن الصلاة"]},{"id":8664,"question":"وهذه رسالة وردتنا من أحد الإخوة لم يذكر اسماً ولا عنواناً وهي رسالة طويلة لعلنا نتمكن من عرض بعض أسئلتها في هذه الحلقة والبقية في حلقات قادمة، يقول: هل يجوز رفع اليدين عند تكبيرة الإحرام فقط أم لابد من رفعها في جميع أركان الصلاة؟","title":"حكم من يرفع اليدين عند تكبيرة الإحرام فقط؟","answer":"الجواب: السنة: رفع اليدين عند الإحرام، وعند الركوع، وعند الرفع منه، وعند القيام من التشهد الأول إلى الثالثة، وليس ذلك واجباً بل هو سنة فعله المصطفى صلى الله عليه وسلم وفعله خلفاؤه الراشدون، وهو المنقول عن أصحاب النبي ﷺ، فالسنة للمؤمن أن يفعل ذلك في جميع الصلوات وهكذا المؤمنة؛ لأن الأصل أن الرجال والنساء سواء في الأحكام إلا ما خصه الدليل، فالسنة أن يرفع يديه عند التكبيرة الأولى حيال منكبيه أو حيال أذنيه، وهكذا عند الركوع، وهكذا عند الرفع منه، وهكذا عند القيام من التشهد الأول إلى الثالثة كما جاءت به الأخبار الصحيحة عن رسول الله عليه الصلاة والسلام، وذلك مستحب وسنة وليس بواجب، ولو صلى ولم يرفع صحت صلاته. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6797/حكم-من-يرفع-اليدين-عند-تكبيرة-الاحرام-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21402.mp3","categories":["سنن الصلاة"]},{"id":8831,"question":"السؤال الأول يقول: عندما تقوم في الصلاة كم مرة ترفع يديك؟","title":"ما عدد مواضع رفع اليدين في الصلاة؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد دلت سنة رسول الله ﷺ على أن المشروع للمؤمن في الصلاة أن يرفع يديه في أربعة مواضع، في الرباعية والثلاثية، الأول: عند الإحرام، فيرفع يديه مع التكبير إلى حذو منكبيه، أو إلى فروع أذنيه، هكذا فعل النبي ﷺ تارة كذا وتارة كذا.\nالموضع الثاني: عند الركوع، يرفع يديه عند قوله: (الله أكبر) حيال منكبيه أو حيال أذنيه.\nالموضع الثالث: عند رفعه من الركوع، فيرفع يديه عند قوله: سمع الله لمن حمده، إذا كان إمامًا أو منفردًا، ويرفع المأموم عند قوله: ربنا ولك الحمد.\nوالموضع الرابع: إذا قام من التشهد الأول في الرباعية كالظهر والعصر والعشاء، أو الثلاثية كالمغرب، إذا قام إلى الثالثة بعد التشهد الأول، إذا قام إلى الثالثة يقول: (الله أكبر) رافعًا يديه.\nكل هذه ثبتت عن رسول الله عليه الصلاة والسلام من حديث ابن عمر ، ومن حديث علي ، وبعضها من حديث مالك بن الحويرث  ومن أحاديث أخرى. نعم.","link":"https://binbaz.org.sa/fatwas/6986/ما-عدد-مواضع-رفع-اليدين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_165/16501.mp3","categories":["سنن الصلاة"]},{"id":8832,"question":"في الركوع عندما تقول: سمع الله لمن حمده، هل ترفع يديك وتقول: ربنا ولك الحمد، وتضع يديك فوق الصدر، أي: تعيدهما إلى مكانهما السابق اليدين، نرجو الإفادة؟","title":"حكم ضم اليدين بعد الرفع من الركوع","answer":"الجواب: نعم، مثل ما تقدم، هذا الموضع الثالث، عند الرفع من الركوع يرفع يديه إذا كان مأموم يقول: ربنا ولك الحمد، وإن كان إمامًا أو منفردًا قال: سمع الله لمن حمده، ثم قال بعدها: ربنا ولك الحمد حمدًا كثيرًا طيبًا مباركًا فيه ملء السماوات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد، يقول هذا الإمام والمأموم والمنفرد، لكن الإمام والمنفرد يختصان بقولهما: سمع الله لمن حمده، أما ربنا ولك الحمد.. إلى آخره هذا مشترك، والمأموم يقول ذلك عند الرفع من الركوع، يقول: ربنا ولك الحمد؛ لأن الرسول ﷺ قال : إنما جعل الإمام ليؤتم به فلا تختلفوا عليه، فإذا كبر فكبروا، وإذا ركع فاركعوا، وإذا قال: سمع الله لمن حمده، فقولوا: ربنا ولك الحمد، نعم، ويضع يديه على صدره، إذا رفع من الركوع يعيدهما إلى مكانهما الأول هذا هو الأفضل والأرجح، يعيدهما إلى مكانهما الأول واضعًا لهما على صدره حتى يخر ساجدًا كما كان كذلك قبل الركوع، ومن قال: إنه يرسلهما بعد الركوع فقد خالف السنة. نعم.","link":"https://binbaz.org.sa/fatwas/6987/حكم-ضم-اليدين-بعد-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_165/16502.mp3","categories":["سنن الصلاة"]},{"id":8833,"question":"يسأل إخوتنا أيضًا ويقولون: الطمأنينة برهة بعد السجدة الثانية عند القيام إلى الركعة الثانية أو الرابعة هل هي ضرورة من سنة سيدنا ﷺ؟","title":"هل جلسة الاستراحة مستحبة؟","answer":"الجواب: هذه جلسة تسمى جلسة الاستراحة بعد الأولى وبعد الثالثة، بعد الأولى في كل صلاة، وبعد الثالثة في الرباعية، كان النبي ﷺ إذا نهض من الأولى من السجدة الثانية في الأولى ومن السجدة الثانية في الثالثة جلس قليلًا كجلوسه بين السجدتين ثم نهض، هذا هو الغالب من فعله ﷺ وربما ترك ذلك، فدل ذلك على أنها مستحبة وسنة وليست واجبة، وليس فيها ذكر ولا دعاء، بل جلسة خفيفة ثم ينهض إلى الثانية وإلى الرابعة. نعم.","link":"https://binbaz.org.sa/fatwas/6988/هل-جلسة-الاستراحة-مستحبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_165/16503.mp3","categories":["سنن الصلاة"]},{"id":8834,"question":"السؤال الأخير الذي نعرضه في هذه الحلقة: في التشهد الأخير للصلاة تظل أصبع السبابة تتحرك حتى نسلم، هل هذا ورد عن سنة سيدنا محمد ﷺ؟","title":"حكم تحريك السبابة في التشهد","answer":"الجواب: الوارد في السبابة أنها واقفة بس، يشير بها إشارة واقفة وقوفًا فيه انحناء، هذا هو السنة كما جاءت به الأحاديث عن رسول الله عليه الصلاة والسلام من حديث ابن عمر ومن حديث وائل بن حجر ومن أحاديث أخرى، أما الحركة فقد ورد في بعض الروايات عند الدعاء، وبعض أهل العلم قال: إن المراد بالحركة الإشارة وأنها لا تخالف، كما قاله البيهقي قال: لعل الحركة هي إشارة، فلا تخالف بين الروايتين، والإشارة هي بنصب الإصبع السبابة نصبًا غير كامل إشارة للتوحيد، إشارة إلى أن الله سبحانه هو الواحد في ذاته وفي أسمائه وصفاته، وفي استحقاقه العبادة جل وعلا.\nوورد في بعض الروايات أنه ربما حركها عند الدعاء، فإذا حركها عند الدعاء فلا بأس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6989/حكم-تحريك-السبابة-في-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_165/16504_01.mp3","categories":["سنن الصلاة"]},{"id":9139,"question":"الرسالة التالية وصلت إلى البرنامج من المستمع عبدالعزيز حسين إبراهيم سوداني يعمل في المملكة في بريد رابغ، يقول في رسالته: بسم الله الرحمن الرحيم وما توفيقي إلا بالله، السؤال الأول يقول فيه: إنني سمعت كثيراً من المصلين يقولون بعد تكبيرة الإحرام مباشرة أدعية مثل: وجهت وجهي إلى فاطر السماء والأرض، أو إلى الكعبة الشريفة، نويت أن أصلي صلاة العصر أو العشاء، ثم بعد ذلك يقول: الله أكبر ويدخل في الصلاة، فما رأيكم في هذا، أفيدونا أفادكم الله؟","title":"حكم دعاء الاستفتاح والجهر بالنية قبل الدخول في الصلاة","answer":"الجواب: السنة للمؤمن إذا قام إلى الصلاة أن يستحضر عظمة ربه وأن هذه الصلاة لها شأن عظيم، وأن الخشوع فيها مطلوب، كما قال الله : قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]، فيقوم بهذه النية بنية الدخول فيها، وإذا كبر الإمام قال بعده: الله أكبر، وإن كان منفرداً لمرض منعه من الجماعة أو في النافلة فإنه يكبر يقول: (الله أكبر) أول ما يبدأ الصلاة، ولا يشرع له أن يقول: نويت أن أصلي كذا وكذا، هذا شيء لا أصل له، والصواب أنه غير مشروع بل هو بدعة؛ لأن الرسول ﷺ ما كان يقول عند البدء بالصلاة: نويت أن أصلي كذا وكذا، وما كان أصحابه يقولون ذلك، ولا الأئمة الأربعة، ولا غيرهم من أهل العلم المعروفين من أئمة السلف الصالح. فالسنة للمؤمن والمؤمنة أن يبدأا الصلاة بقوله: الله أكبر، ولا يأتي بقوله: نويت أن أصلي الظهر كذا والعصر كذا.. الفجر كذا.. الجمعة كذا، هذا لا أصل له، ولكن ينوي في قلبه أنه قائم للصلاة المعينة الظهر أو العصر أو المغرب أو العشاء ويكفي، القلب هو محل النية.\nأما وجهت وجهي فهذا يقوله بعد الدخول، هذا يسمى: الاستفتاح، إذا كبر يقول الاستفتاح المشروع الذي كان يفعله النبي ﷺ، وقد صح عنه ﷺ أنواع من الاستفتاحات أخصرها وأوجزها: سبحانك اللهم وبحمدك وتبارك اسمك وتعالى جدك ولا إله غيرك، يقول هذا بعد التكبير، يقوله الرجل والمرأة في الفرض والنفل: سبحانك اللهم وبحمدك وتبارك اسمك وتعالى جدك ولا إله غيرك ومعنى: تعالى جدك يعني: عظمتك، جد الله: عظمته سبحانه وتعالى، ولا إله غيرك يعني: لا معبود بحق في الأرض ولا في السماء سواك يا ربنا، فهو المعبود بالحق سبحانه وتعالى، وما عبده الناس من دون الله من قبور وأصحاب قبور أو أنبياء أو صالحين أو كواكب أو صنم أو شجر كله باطل، أما المعبود بالحق فهو الله وحده سبحانه وتعالى، وهذا معنى: لا إله غيرك، أي: لا معبود بحق سواك، قال الله تعالى: ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62].\nويشرع استفتاحاً آخر كان الرسول يستعمله عليه الصلاة والسلام وهو ثابت عنه: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد، هذا أيضاً كان يستعمله النبي ﷺ وهو ثابت عنه في الصحيحين، فإذا فعله الإنسان قبل أن يقرأ: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد هذا مستحب وليس بواجب قبل أن يقرأ وبعد أن يكبر، وهناك نوع ثالث من الاستفتاح يقول: وجهت وجهي للذي فطر السموات والأرض حنيفاً وما أنا من المشركين، إن صلاتي ونسكي ومحياي ومماتي لله رب العالمين لا شريك له، وبذلك أمرت وأنا من المسلمين، اللهم أنت الملك لا إله إلا أنت، أنت ربي وأنا عبدك، ظلمت نفسي واعترفت بذنبي فاغفر لي ذنوبي جميعاً إنه لا يغفر الذنوب إلا أنت، واهدني لأحسن الأخلاق لا يهدي لأحسنها إلا أنت، واصرف عني سيئها لا يصرف عني سيئها إلا أنت، لبيك وسعديك والخير كله في يديك، والشر ليس إليك، أنا بك وإليك، تباركت وتعاليت، أستغفرك وأتوب إليك، هذا نوع من الاستفتاح وهو صحيح ثابت، كان في الغالب يستعمله بالليل عليه الصلاة والسلام، وفي التطوع وإذا استعمله الإنسان في الفريضة فلا بأس؛ لأن شأنهما واحد إلا ما خصه الدليل، ولكنه طويل ليس كل واحد يحفظه، فالأول أخصر وأيسر على العامة من الرجال والنساء: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك ولا إله غيرك، ثم يقول: أعوذ بالله من الشيطان الرجيم، بسم الله الرحمن الرحيم، ويقرأ الحمد، ثم ما تيسر معها بعد ذلك، هذا هو المشروع. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7299/حكم-دعاء-الاستفتاح-والجهر-بالنية-قبل-الدخول-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_230/23002.mp3","categories":["سنن الصلاة","التكبير والاستفتاح"]},{"id":9147,"question":"السؤال الثالث والأخير في رسالة الأخ هيثم سالم حيدرة من عدن اليمن الديمقراطية يقول فيه: ما حكم مسألة الضم بعد الاعتدال من الركوع؛ لأن الشيخ محمد ناصر الدين الألباني في كتابه: (صفة صلاة النبي ﷺ) يقول: بأنه لا يشك في أن ذلك بدعة، أفيدونا جزاكم الله خيراً؟","title":"حكم الضم بعد الاعتدال من الركوع","answer":"الجواب: الضم بعد القيام من الركوع سنة وهو يضع يمينه على شماله على صدره كما فعل قبل الركوع، هذا هو المحفوظ من الأحاديث الصحيحة عن رسول الله صلى الله عليه وسلم، روى ذلك وائل بن حجر عن النبي ﷺ بإسناد صحيح، وروى ما يدل على معناه سهل بن سعد عن النبي ﷺ: أن الرجل كان يؤمر في عهد النبي ﷺ أن يضع يده اليمنى على ذراعه اليسرى في الصلاة -قال أبو حازم الراوي عن سهل -: لا أعلمه إلا ينمي ذلك إلى الرسول ﷺ ، رواه البخاري في الصحيح.\nفهذا هو الصواب والحق أن ضم اليمين إلى اليسار يعني وضع اليمين على الكف اليسرى والرسغ والساعد بعد الركوع وقبله حال القيام هو السنة، أما أخونا الفاضل الشيخ العلامة محمد ناصر الدين الألباني فقد ذكر ما ذكره السائل وأن هذا بدعة، وقد وهم في هذا وفقه الله، وكل إنسان له أوهام، كل عالم له أوهام، وأخونا الشيخ ناصر الدين من خيرة علماء المسلمين، وهو ممن نعرفه ونشهد له بالفضل والعناية بالسنة والحرص عليها، وقد ألف فيها ما ألف من المؤلفات الطيبة النافعة، ولكنه كغيره من العلماء يخطئ ويصيب، فله أشياء أخطأ فيها عفا الله عنه، كما لغيره من الأئمة كـمالك والشافعي وأحمد وغيرهم من الأئمة الكبار، كل واحد له أشياء أخطأ فيها وخفي عليه فيها الحق، إما لأنه لم يطلع على الحديث أو لم يبلغه بوجه يصح أو لأسباب أخرى كما بين ذلك أبو العباس ابن تيمية في كتابه: (رفع الملام عن أئمة الإسلام) فكل عالم قد يفوته شيء وله فيه عذره رضي الله عنهم ورحمهم، فأخونا العلامة الشيخ ناصر الدين الألباني من جملة أولئك الأخيار الذين لهم عذرهم فيما أخطئوا فيه، وقد كتبنا في هذا كتاباً بينا ما فيه الصواب ونشرت من مدة وهي موجودة وتوزع، فينبغي للسائل أن يراجعها إن كانت عنده، أو يكتب لنا ونرسلها له إن شاء الله.\nفالخلاصة: أن السنة أن يضم يديه بعد الركوع كما قبل الركوع، هذا هو الأفضل يضع اليمنى على كفه اليسرى والرسغ والساعد على صدره كما فعل قبل الركوع، لقول وائل : رأيت النبي ﷺ إذا كان قائماً في الصلاة يضع يمينه على شماله، وقوله: إذا كان قائماً في الصلاة يشمل هذا وهذا، ولم يحفظ عن النبي ﷺ ولا عن أحد من أصحابه فيما نعلم أنه أرسل يديه بعد الركوع، فما قاله الشيخ هنا الشيخ العلامة ناصر الدين: أنه بدعة غلطة كبيرة نسأل الله أن يعفو عنه. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7303/حكم-الضم-بعد-الاعتدال-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_230/23006.mp3","categories":["سنن الصلاة"]},{"id":9205,"question":"هل صحيح يجب أن يرفع المسلم يديه عند الركوع والرفع من الركوع مثلما فعل في التكبيرة الأولى، بمعنى: أن يقول: الله أكبر ثم يرفع يديه على مستوى أذنيه، وهل يصح للمرأة فعل هذا؟","title":"مواضع رفع اليدين في الصلاة للرجل والمرأة","answer":"الجواب: هذا سنة وليس بفريضة، أن يرفع يديه عند الإحرام إلى حيال أذنيه أو إلى حيال منكبيه كما فعل النبي ﷺ، وهكذا عند الركوع وعند الرفع منه، وهكذا عند القيام من التشهد الأول إلى الثالثة يرفع يديه ويجعلهما حيال منكبيه أو حيال أذنيه، تارة كذا وتارة كذا اقتداء بالنبي عليه الصلاة والسلام، وهذه سنة مؤكدة ولو تركها أو بعضها صحت صلاته.\nوالمرأة مثل الرجل في هذا على الصحيح؛ لأن الرسول ﷺ لم يخصها في هذا بشيء، الصحيح: أنها مثل الرجل ترفع يديها عند الإحرام وعند الركوع وعند الرفع منه وعند القيام للتشهد الأول. نعم.","link":"https://binbaz.org.sa/fatwas/7365/مواضع-رفع-اليدين-في-الصلاة-للرجل-والمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_181/18112.mp3","categories":["سنن الصلاة"]},{"id":9519,"question":"بقي له أيضاً سؤال أخير يقول: أرى أيضاً بعض المصلين وهو في التشهد الأخير يرفع السبابتين اليمنى واليسرى عندما يصل في التشهد إلى قوله: أشهد أن لا إله إلا الله وأن محمداً عبده ورسوله، فهل هذا الفعل صحيح؟","title":"حكم الإشارة بالسبابة في التشهد وكيفية ذلك","answer":"الجواب: السنة رفع السبابة اليمنى فقط، في التشهد الأول والأخير يشير بالسبابة اليمنى ويقبض أصابعه كلها ويشير بالسبابة عند ذكر الله عند الدعاء، أو يقبض الخنصر والبنصر ويحلق الإبهام مع الوسطى ويشير بالسبابة سنتان، إن شاء قبض أصابعه كلها وأشار بالسبابة وإن شاء قبض الخنصر مع البنصر وحلق الإبهام والوسطى وأشار بالسبابة، كل هذا جاء عن النبي ﷺ.\nوأما اليسرى فلا يشير بشيء بل يبسطها على فخذه وأطرافها على ركبته ولا يشير بشيء، لا بالسبابة ولا بغيرها هذه السنة، يده اليمنى يقبض أصابعها ويشير بالسبابة وإن شاء قبض الخنصر والبنصر وحلق الإبهام والوسطى وأشار بالسبابة سنتان، يفعل هذه تارة وهذه تارة.\nأما اليسرى فإنه يبسطها بسطا على فخذه أو على ركبته أو على فخذه وأطرافها على ركبته، جاءت السنة بهذا كله عن النبي عليه الصلاة والسلام. نعم.\nالمقدم: أحسن الله إليكم.\nالشيخ: ولا يشير بالسبابة اليسرى لا يشير بها الإشارة باليمنى فقط. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7688/حكم-الاشارة-بالسبابة-في-التشهد-وكيفية-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_244/24407.mp3","categories":["سنن الصلاة"]},{"id":9561,"question":"السؤال الثاني في رسالة الأخ صبري الجبوري من العراق يقول فيه: هل يجوز سبل اليدين أثناء الصلاة أم التكتف، وأيهما أصح أفيدونا أفادكم الله؟","title":"حكم إرسال اليدين أثناء القيام في الصلاة","answer":"الجواب: القبض هو السنة، وهو أن يضم يده اليمنى على يده اليسرى على صدره هذا هو السنة وهذا هو الأفضل، ولو أرسل يديه على جنبيه صحت صلاته لكنه مكروه، والأفضل وهو السنة أن يضع يمينه على شماله على كفه اليسرى ورسغه وساعده لما ثبت في الحديث الصحيح عن وائل بن حجر  قال: رأيت النبي ﷺ يضع يده اليمنى على كفه اليسرى والرسغ والساعد إذا كان قائمًا في الصلاة.\nوفي صحيح البخاري رحمة الله عليه عن أبي حازم عن سهل بن سعد رضي الله تعالى عنه أنه قال: كان الرجل يؤمر أن يضع يده اليمنى على ذراعه اليسرى في الصلاة قال أبو حازم: ولا أعلمه إلا ينمي ذلك -يعني يرفع ذلك- إلى النبي ﷺ، فهو يدل على أن وضع اليمين على الشمال في الصلاة على صدره هو السنة وهو الأفضل.\nوقد جاء في هذا عدة أخبار عن النبي ﷺ. نعم.","link":"https://binbaz.org.sa/fatwas/7726/حكم-ارسال-اليدين-اثناء-القيام-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19302.mp3","categories":["سنن الصلاة"]},{"id":9647,"question":"السؤال الثالث يقول فيه: بعض العلماء يقول: إن الضم في الصلاة سنة عن المصطفى ﷺ، والبعض الآخر يقول: إنه بدعة -أي: الضم بعد القيام من الركوع- أفيدونا أفادكم الله؟","title":"حكم الضم بعد القيام من الركوع","answer":"الجواب: الضم سنة حال القيام في الصلاة قبل الركوع وبعده، هذا هو الصواب، ومن قال: إنه بدعة فقد غلط غلطًا بينًا، فقد ثبت في الحديث الصحيح عن وائل بن حجر  قال: رأيت النبي ﷺ إذا كان قائمًا في الصلاة يضع يده اليمنى على كفه اليسرى والرسغ والساعد رواه أبو داود والنسائي بإسناد صحيح.\nوكذلك قال قبيصة بن هلب الطائي عن أبيه: أن النبي ﷺ كان يضع يمينه على شماله على صدره حال وقوفه في الصلاة رواه أحمد بإسناد جيد وهكذا روى البخاري في الصحيح عن سهل بن سعد من طريق أبي حازم قال: كان الرجل يؤمر أن يضع يده اليمنى على ذراعه اليسرى في الصلاة قال أبو حازم: ولا أعلمه إلا ينمي ذلك إلى النبي ﷺ، فهذا يدل على أن القائم في الصلاة يضع يمينه على شماله، وهذا يعم القيام قبل الركوع وبعده، وهذا هو الصواب. نعم.","link":"https://binbaz.org.sa/fatwas/7813/حكم-الضم-بعد-القيام-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19410.mp3","categories":["سنن الصلاة"]},{"id":9659,"question":"وما حكم دعاء الاستفتاح والتعوذ من عذاب جهنم وعذاب القبر وفتنة المحيا والممات والمسيح الدجال؟","title":"حكم دعاء الاستفتاح والتعوذ من الأربع بعد التشهد","answer":"الجواب: كله سنة.. كله سنة.. الاستفتاح بـ سبحانك اللهم وبحمدك وتبارك اسمك وتعالى جدك ولا إله غيرك أواللهم باعد بيني وبين خطاياي الحديث، أو غيرهما من الاستفتاحات كله سنة ومستحب وليس بلازم إنما هو مستحب، إذا كبر تكبيرة الإحرام قبل أن يقرأ يقول: سبحانك الله وبحمدك وتبارك اسمك وتعالى جدك ولا إله غيرك في الفرض والنفل جميعاً. أو يأتي باستفتاح آخر مما صح عن النبي ﷺ، ومن ذلك ما صح عنه ﷺ أنه كان يقول -أول ما يكبر، يسكت هنيهة- ويقول: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد هذا أصح ما ورد عنه عليه الصلاة والسلام.\nوإن استفتح بغير ذلك من الاستفتاحات الصحيحة فهو سنة، واحد منها يكفي، وأقصرها: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك هذا أقصرها، يستطيع حفظه كل أحد من الناس، ثم بعد هذا يقول: أعوذ بالله من الشيطان الرجيم، بِسْمِ اللَّهِ الْرَّحمَنِ الْرَّحَيمِ [الفاتحة:1] ويقرأ الفاتحة.\nوأما التعوذ من عذاب جهنم ومن عذاب القبر إلى آخره فهذا سنة مؤكدة في آخر الصلاة قبل أن يسلم، يقول: «أعوذ بالله من عذاب جهنم ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال» سنة مؤكدة، كان النبي ﷺ يفعلها ويأمر بها.\nويستحب له الدعاء بغير هذا، مثل: اللهم أعني على ذكرك وشكرك وحسن عبادتك اللهم اغفر لي ولوالدي اللهم إني ظلمت نفسي ظلماً كثيراً ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أسرفت، وما أنت أعلم به مني، أنت المقدم وأنت المؤخر لا إله إلا أنت كل هذا صح عن النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/7832/حكم-دعاء-الاستفتاح-والتعوذ-من-الاربع-بعد-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_251/25114.mp3","categories":["التكبير والاستفتاح","سنن الصلاة"]},{"id":9676,"question":"هذه رسالة وردت إلينا من جمهورية تشاد من السائل: عمر عثمان يقول في رسالته: هل تجوز الصلاة خلف إمام لا يجعل يديه على صدره أثناء القيام بل يضعهما ممدودتان أفيدونا أفادكم الله؟","title":"حكم إمامة من يرسل يديه أثناء القيام في الصلاة","answer":"الجواب: نعم وضع اليدين على الصدر سنة ليس بلازم، فلو أرسل يديه صحت الصلاة ولا حرج، قصاراه أنه ترك السنة ترك الأفضل ولا شيء عليه، والصلاة صحيحة، ولا مانع أن يتخذ إماماً للناس، لكن من كان معروفاً بالمحافظة على السنة يكون أولى وأفضل، وإلا فهذا صلاته صحيحة ولو أرسل يديه، ولو لم يضعهما على صدره، فإن السنة لا تمنع الإمامة ترك السنة، فالسنة وضع اليدين على الصدر وضعهما على الفخذين وقت الجلوس، وافتراش الرجل اليسرى وقت الجلوس ونصب اليمنى، كل هذه من السنن، وليست واجبات، ولكنها من مكملات الصلاة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7842/حكم-امامة-من-يرسل-يديه-اثناء-القيام-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_252/25203.mp3","categories":["سنن الصلاة","صلاة الجماعة"]},{"id":9757,"question":"وهذه رسالة وردت إلينا من مصر من حسين فهمي السيد من محافظة الشرقية مركز أبو حماد، يقول في رسالته: إنني صليت في مسجد في المملكة فوجدت الإمام يصلي في نعليه، فهل هذا جائز وخاصة أنني سمعت من بعض الناس أن هذا سنة؟ وما حكم من ينظر في ساعته وينشغل بأمور جانبية في الصلاة، أفيدونا أفادكم الله؟","title":"هل يجوز الصلاة بالنعال في المسجد؟","answer":"الجواب: الصلاة في النعلين ثابتة عن النبي ﷺ، كان يصلي في نعليه عليه الصلاة والسلام، وربما خلعها وجعلها عن يساره وصلى بدون نعلين، فقد صلى منتعلاً وحافياً عليه الصلاة والسلام، فمن صلى في نعليه وهما نظيفتان فلا حرج عليه، وقد ثبت عنه ﷺ أنه كان يصلي ذات يوم بأصحابه فأخبره جبرائيل أن في نعليه قذراً فخلعهما واستمر في صلاته، ثم خلع الناس نعالهم، فلما سلم عليه الصلاة والسلام قال: ما لكم خلعتم نعالكم؟ قالوا: رأيناك خلعت نعليك! قال: إن جبرائيل أخبرني أن بهما قذراً، فإذا أتى أحد المسجد فلينظر، فإن رأى في نعليه أذى فليمسحه ثم ليصل فيهما فدل ذلك على أن الصلاة فيهما سنة وطاعة، وقد فعلها الرسول ﷺ.\nوفي الحديث الآخر: إن اليهود والنصارى لا يصلون في نعالهم ولا في خفافهم فخالفوهم أو كما قال عليه الصلاة والسلام، فهذا كله يدل على أن الصلاة في النعلين أو في الخفاف سنة خلاف ما عمل اليهود والنصارى .\nفإذا صلى فيهما فرضاً أو نفلاً فلا حرج في ذلك، لكن بشرط أن يعتني بهما ويحرص على نظافتهما قبل دخوله المسجد.\nوإن خلعهما إذا كان المسجد مفروشاً إذا خلعهما وجعلهما في محل خاص بالنعال أو عند باب المسجد لئلا يقذر الفراش، فهذا لا بأس به؛ لأن الفرش قد تتأثر بالنعال، وقد يتأثر الناس بما يقع فيها من غبار أو أوساخ، فإذا ترك نعليه عند الباب أو في المحلات المعدة للنعلين، فلعل هذا إن شاء الله يكون مناسباً من باب العناية بنظافة الفرش التي وضعت في المساجد.","link":"https://binbaz.org.sa/fatwas/7918/هل-يجوز-الصلاة-بالنعال-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25609.mp3","categories":["سنن الصلاة"]},{"id":10141,"question":"أيضاً يسأل المستمع حسام عفيف من الرياض ويقول: هل يصح تسبيل الأيادي عند أداء الصلاة بدلاً من أن توضع اليد اليمنى على اليد اليسرى فوق الصدر؟","title":"حكم إسبال اليدين أثناء القيام في الصلاة","answer":"الجواب: السنة الضم، الذي عليه جمهور أهل العلم الضم، وقد صحت بذلك الأحاديث عن رسول الله ﷺ، لكن لو أرسل يديه صحت صلاته وفعل شيئاً مكروهاً لا يبطل الصلاة، وإنما السنة أن يضم يديه إلى صدره فيضع اليمنى كف اليمنى على كف اليسرى والرسغ والساعد، كما جاءت بذلك الأخبار عن رسول الله ﷺ، ومن ذلك ما رواه البخاري في الصحيح عن أبي حازم عن سهل بن سعد  قال: لا أعلمه إلا ينعيه إلى النبي ﷺ قال: كان الرجل يؤمر إذا كان في الصلاة أن يضع يده اليمنى على ذراعه اليسرى في الصلاة وهذا يدل على وجوب الضم، ولكنه عند أهل العلم مستحب، الأمر للاستحباب، ومعلوم أن محل اليدين في الصلاة معروف في الركوع توضع على الركبتين، في السجود على الأرض، في الجلوس على الفخذين أو الركبتين، فما بقي إلا القيام، والقيام توضع اليمنى على كف اليسرى أو ذراعيها على كفها وذراعيها.\nوهكذا في حديث قبيصة بن هلب الطائي أن النبي ﷺ أمر المصلي أن يضع يده اليمنى على كفه اليسرى على صدره.\nوهكذا في حديث وائل بن حجر عند أبي داود والنسائي كلها تدل على أن اليمنى توضع على اليسرى توضع الكف الأيمن على الكف الأيسر والذراع، وفق الله الجميع. نعم.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/8319/حكم-اسبال-اليدين-اثناء-القيام-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_306/30608.mp3","categories":["سنن الصلاة"]},{"id":10323,"question":"يقول: نعلم أن رفع اليدين مع التكبيرات في أربعة مواضع، منها: ما هو بعد الرفع من الركوع، فهل يرفع الإنسان يديه عند قوله: سمع الله لمن حمده، أم بعد استوائه في الركوع وقوله: ربنا ولك الحمد؟","title":"موطن رفع اليدين عند الرفع من الركوع","answer":"الجواب: السنة الرفع عند رفعه من الركوع، عند قوله: سمع الله لمن حمده إن كان إماماً أو منفرداً، وعند قوله: ربنا ولك الحمد إن كان مأموماً، يعني حين الرفع هذا هو السنة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8491/موطن-رفع-اليدين-عند-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_314/31404.mp3","categories":["سنن الصلاة"]},{"id":10549,"question":"يقول: ألاحظ أن الناس عند أداء الصلاة ينقسمون إلى قسمين فيما يعني وضع اليد على الصدر أو الإسبال، أيهما أصح؟ وأيهما فعل الرسول عليه أفضل الصلاة والسلام؟","title":"حكم إرسال اليدين حال القيام في الصلاة","answer":"الجواب: السنة القبض وهذا هو الذي فعله الرسول ﷺ، وهو وضع اليمين على الشمال على الصدر، هذا هو السنة يضع كفه اليمنى على كفه اليسرى على صدره في الصلاة، هذا هو السنة، أما الإسبال فهو خلاف السنة، نسأل الله الهداية للجميع. نعم.\nالمقدم: آمين جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8721/حكم-ارسال-اليدين-حال-القيام-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_321/32102.mp3","categories":["سنن الصلاة"]},{"id":11172,"question":"إذا نسي الإنسان ولم يقرأ سورة بعد الفاتحة حين يصلي، فهل يسجد للسهو أم أن صلاته بطلت؟","title":"حكم من نسي القراءة بعد الفاتحة","answer":"الجواب:  لا. لا حرج عليه، نسي السورة؛ لأنها مستحبة ما هي بواجبة، الواجب الفاتحة، فإذا نسي السورة وركع ليس عليه شيء، وإن سجد فلا بأس لكن لا يلزمه شيء. نعم.","link":"https://binbaz.org.sa/fatwas/9344/حكم-من-نسي-القراءة-بعد-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29019.mp3","categories":["سنن الصلاة","القراءة في الصلاة"]},{"id":11239,"question":"سؤاله الثاني يقول: ما حكم تربيع اليدين في الصلاة؟","title":"ما السنة في هيئة اليدين أثناء الصلاة؟","answer":"الجواب:  لا، لم أفهم معنى التربيع، السنة في الصلاة أن تكون يداه على صدره حال قيامه، وفي الجلوس على فخذيه أو على ركبتيه -بين السجدتين وفي التشهد- وعند السجود على الأرض يعتمد على كفيه على الأرض حيال منكبيه أو حيال أذنيه، وحال الرفع عند الركوع يرفعهما حيال منكبيه أو حيال أذنيه، عند الرفع من الركوع، وعند التكبير للإحرام، وعند الركوع يرفع يديه حيال منكبيه أو حيال أذنيه، أما التربيع الذي سأل عنه السائل فلا أعرف ما هو التربيع، لكن هذه الصفات التي فعلها النبي ﷺ. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9411/ما-السنة-في-هيىة-اليدين-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29120.mp3","categories":["سنن الصلاة"]},{"id":11289,"question":"إذا جاءت الوسوسة للمصلي خلال صلاته فهل يجوز التعوذ أثناء الصلاة، جزاكم الله خيرًا؟","title":"حكم الاستعاذة أثناء الصلاة دفعاً للوسواس","answer":"الجواب:  نعم سنة التعوذ، إذا شعر بالوسوسة يتعوذ بالله من الشيطان ثلاث مرات يتفل عن يساره ثلاث مرات، ويتعوذ بالله من الشيطان كما أمر النبي ﷺ بعض الصحابة في ذلك، فالسنة له أن يتعوذ بالله من الشيطان وينفث عن يساره ثلاث مرات، ويقبل على صلاته بقلبه، ويستحضر عظمة الله  ويزول الوسواس إن شاء الله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9487/حكم-الاستعاذة-اثناء-الصلاة-دفعا-للوسواس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37619.mp3","categories":["سنن الصلاة"]},{"id":11333,"question":"هذه رسالة وصلت من الجزائر، السائل لم يذكر الاسم في هذه الرسالة ويقول: مما ثبت عن النبي ﷺ رفع اليدين عند القيام من الركعتين في صلاة ثلاثية أو رباعية، ما الراجح يا سماحة الشيخ من الأدلة في رفع اليدين قبل القيام أم عندما يستوي المصلي قائمًا؟","title":"السنة في رفع اليدين عند القيام للركعة الثالثة","answer":"الجواب:  السنة عند القيام يرفعها عند قيامه من التشهد الأول إلى الثالثة، عند قيامه يكون رافعًا لها حيال منكبيه أو حيال أذنيه حال الرفع، هذا هو السنة. نعم.","link":"https://binbaz.org.sa/fatwas/9515/السنة-في-رفع-اليدين-عند-القيام-للركعة-الثالثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_292/29212.mp3","categories":["سنن الصلاة"]},{"id":11770,"question":"يسأل سماحتكم عن أولئك الذين يصلون، وقد أسبلوا أيديهم؟","title":"حكم إرسال اليدين في الصلاة حال القيام","answer":"الجواب:  هذا خلاف السنة، مكروه، إسبال اليدين في الصلاة مكروه، السنة ضمهما، يجعل اليمنى على اليسرى فوق صدره، هذا السنة، أما إرسالهما فهو خلاف السنة، لكن الصلاة صحيحة، عمل مكروه والصلاة صحيحة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9958/حكم-ارسال-اليدين-في-الصلاة-حال-القيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39420.mp3","categories":["سنن الصلاة","مكروهات الصلاة"]},{"id":11796,"question":"المستمع أيضًا يسأل ويقول: إمام صلى بنا صلاة سريةـ إنما هو قد جهر فيها، فما هو توجيهكم؟","title":"ما حكم جهر الإمام في الصلاة السرية؟","answer":"الجواب:  لا شيء عليه، وإن سجد للسهو؛ فهو حسن، ولكن لا يلزمه ذلك؛ لأن الجهر والإسرار سنتان، فلو جهر في السر، أو أسر في الجهر؛ فلا شيء عليه والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9980/ما-حكم-جهر-الامام-في-الصلاة-السرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_422/42213.mp3","categories":["القراءة في الصلاة","سنن الصلاة"]},{"id":12156,"question":"كم يجب على المرأة أن ترفع يديها في الصلاة عند التكبير؟","title":"صفة رفع اليدين في الصلاة بالنسبة للمرأة","answer":"الجواب:  مثل الرجل، ترفع يديها عند الإحرام، وعند الركوع، وعند الرفع منه، وعند القيام من التشهد الأول إلى الثالثة، هذا السنة للرجل والمرأة، ترفع اليدين حيال منكبيها، أو حيال أذنيها، عند التكبيرة الأولى، وعند الركوع، وعند الرفع من الركوع، وعند القيام من التشهد الأول، وتفعل مثل الرجل إذا جلست تفترش بين السجدتين، وفي التشهد الأول، تتورك في التشهد الأخير، هذا هو الصواب؛ لأن الرسول ﷺ قال: صلوا كما رأيتموني أصلي ولم يقل للمرأة كذا، والرجل كذا، فالأحاديث عامة تعم الرجال والنساء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10341/صفة-رفع-اليدين-في-الصلاة-بالنسبة-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_441/44106.mp3","categories":["سنن الصلاة"]},{"id":12189,"question":"ماذا عن الجلسة الخفيفة قبل القيام؟","title":"هل جلسة الاستراحة مستحبة؟","answer":"الجواب:  أما الجلسة فهذه سنة مستحبة، ويقال لها: جلسة الاستراحة، وليست واجبة، من فعلها؛ فقد أحسن، ومن لا؛ فلا حرج، وقد ثبت عن النبي ﷺ أنه كان يفعلها في صلاته ﷺ وقد ذهب بعض أهل العلم إلى أنها غير مستحبة، وأن فعل النبي ﷺ محمول على أنه كان بعدما كبر سنة وثقل. والصواب أنها مستحبة مطلقًا، هذا هو الصواب؛ لأنها ثبت عن النبي ﷺ وعن جماعة من الصحابة  فدل ذلك على استحبابها بعد الأولى والثالثة في الرباعية، بعد الأولى في جميع الصلوات، وبعد الثالثة في الرباعية، جلسة خفيفة، مثل الجلوس بين السجدتين. وهكذا السنة أن يضع كفه اليمنى على كفه اليسرى والرسغ والساعد إذا كان واقفًا، يضع كفه اليمنى على كفه اليسرى، وعلى الرسغ والساعد، تكون اليد على بعض الكف، على الكف، وبعضه على الرسغ، وبعض الأصابع على الساعد، كما فعله النبي ﷺ كما ثبت هذا في حديث وائل بن حجر  نعم.","link":"https://binbaz.org.sa/fatwas/10375/هل-جلسة-الاستراحة-مستحبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44316.mp3","categories":["سنن الصلاة"]},{"id":12190,"question":"ماذا عن التورك للمأموم في الصف المزدحم؟","title":"حكم ترك التورك في التشهد عند ازدحام الصف","answer":"الجواب:  إذا دعت الحاجة إلى التضام، وعدم التورك لا يتورك، التورك سنة، مستحب في التشهد الأخير، فإذا كان يؤذي به إخوانه؛ فلا يتورك، يجلس على رجله اليسرى كجلوسه بين السجدتين وهو في التشهد الأول؛ لأن إيذاء إخوانه محرم، فلا يستبيح المحرم بمستحب، يترك المستحب حتى يتوقى المحرم، فإيذاء إخوانه، والتعدي عليهم أمر لا يجوز، فإذا كانت مضايقة في الصف؛ فإنه لا يتورك، بل يجلس على رجله اليسرى كحاله بين السجدتين إذا استطاع ذلك، أما إذا كان مريضًا، أو عاجزًا لا يستطيع؛ فيعمل ما يستطيع، ويتوقى الإيذاء مهما استطاع، نعم.","link":"https://binbaz.org.sa/fatwas/10376/حكم-ترك-التورك-في-التشهد-عند-ازدحام-الصف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44317.mp3","categories":["سنن الصلاة"]},{"id":12372,"question":"بعض الناس إذا وقف في صلاته، وراء الإمام لا يضع اليد اليمنى على اليسرى، بل يقف مسبلًا يديه، وهذا في بعض الناس ربما تكون عادة، أو مذهبًا فما هو توجيهكم؟ جزاكم الله خيرًا.","title":"حكم إرسال اليدين في الصلاة","answer":"الجواب:  المشروع للمؤمن أن يضع يده اليمنى على كفه اليسرى، على صدره في الصلاة، لا يسبل، لا يرسلهما، لكن لو أرسلهما الصلاة صحيحة، والكراهة أنه فعل مكروهًا لا ينبغي، وإلا الصلاة صحيحة. المقصود: أنه ترك السنة، السنة أن يضع يده اليمنى على كفه اليسرى، على صدره حال كونه قائمًا في الصلاة، هذا هو المشروع، فلو أرسلهما صحت الصلاة، وترك الأحوط، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10570/حكم-ارسال-اليدين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40008.mp3","categories":["سنن الصلاة"]},{"id":12858,"question":"من العراق، بغداد المستمع: ضرار العاني بعث يسأل ويقول: أرجو أن توضحوا لي الحكم الشرعي في وضع اليدين بعد النهوض من الركوع، جزاكم الله خيرًا.","title":"حكم ضم اليدين على الصدر بعد الرفع من الركوع","answer":"الجواب:  السنة وضعها على الصدر كما قبل الركوع هذا هو السنة، لما ثبت عنه ﷺ من حديث وائل بن حجر: \"أنه ﷺ كان إذا كان قائمًا في الصلاة؛ وضع يمينه على يساره، وضع كفه اليمنى على كفه اليسرى، والرسغ والساعد، هكذا رواه أبو داود والنسائي وغيرهما بإسناد صحيح عن وائل بن حجر. وفي صحيح البخاري -رحمه الله- عن أبي حازم، عن سهل بن سعد، قال -لا أعلمه إلا ينميه إلى النبي ﷺ- قال: \"كان الرجل يؤمر إذا كان في الصلاة أن يضع يده اليمنى على ذراعه اليسرى في الصلاة\" وهذا يعم ما قبل الركوع، وما بعد الركوع. فالسنة للمؤمن في الصلا،ة وهكذا المؤمنة وضع اليمين على الشمال قبل الركوع، وبعد الركوع. وأما ما وقع في صفة صلاة النبي ﷺ لأخينا العلامة الفاضل الشيخ: محمد ناصر الدين الألباني من قوله: إن وضعهما بعد الركوع بدعة، هذا أمر غلط، قد نبهنا على هذا غير مرة، وكتبنا في ذلك ما يوجب بيان هذا الأمر، وأرجو أن فضيلته يرجع عن هذا القول؛ لأنه خلاف الصواب، وأسال الله أن يوفق الجميع لما يرضيه. المقدم: اللهم آمين، جزاكم الله خيرًا، ووفق الجميع إلى ما فيه الخير والصلاح.","link":"https://binbaz.org.sa/fatwas/11073/حكم-ضم-اليدين-على-الصدر-بعد-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_465/46508.mp3","categories":["سنن الصلاة"]},{"id":13437,"question":"هل يجوز الدعاء بعد كل صلاة مكتوبة؟ وما معنى حديث رسول الله ﷺ: أي الدعاء أسمع؟ قال: جوف الليل الآخر، ودبر الصلوات المكتوبات؟","title":"حكم الدعاء بعد التشهد قبل السلام من الصلاة","answer":"الجواب: الدعاء في آخر الصلاة مستحب وسنة، قربة قبل السلام، هذا هو الأفضل، يدعو بما يسر الله له قبل السلام من خير الدنيا والآخرة، ومن أفضل الدعاء قبل السلام: التعوذ بالله من عذاب جهنم، ومن عذاب القبر،، ومن فتنة المحيا والممات ومن فتنة المسيح الدجال، وهكذا يقول: اللهم أعني على ذكرك، وشكرك، وحسن عبادتك اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك، وارحمني إنك أنت الغفور الرحيم اللهم اغفر لي ما قدمت وما أخرت، وما أسررت وما أعلنت، وما أسرفت وما أنت أعلم به مني، أنت المقدم وأنت المؤخر لا إله إلا أنت اللهم إني أعوذ بك من البخل وأعوذ بك من الجبن، وأعوذ بك أن أرد إلى أرذل العمر، وأعوذ بك من فتنة الدنيا، وأعوذ بك من عذاب القبر كل هذه الأدعية صحيحة ثابتة عن رسول الله ﷺ، ويستحب الدعاء بها في آخر الصلاة. ودعاء اللهم إني ظلمت نفسي ظلمًا كثيرًا هذا يدعى به في آخر الصلاة، وفي كل وقت؛ لأن الرسول ﷺ لما سأله الصديق قال: يا رسول الله! علمني دعاء أدعو به في صلاتي -وفي رواية وفي بيتي- قال: قل: اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك، وارحمني إنك أنت الغفور الرحيم. وهذا يدخل فيه الدعاء في آخر الصلاة، وفي السجود، وبين السجدتين، كله داخل في هذا، وهكذا في بقية الأوقات، في بيته في الطريق في أثناء الليل إلى غير ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11734/حكم-الدعاء-بعد-التشهد-قبل-السلام-من-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47715.mp3","categories":["سنن الصلاة"]},{"id":13826,"question":"كيف كان هدي النبي ﷺ في وضع اليدين في الصلاة؟ وهل عليَّ حرج عندما أضع ذلك بين السرة والصدر؟","title":"السنة في وضع اليدين في الصلاة","answer":"الجواب: السنة في وضع اليدين في الصلاة على الصدر، هذا هو المحفوظ عن النبي ﷺ من حديث وائل بن حجر، ومن حديث سهل بن سعد، ومن حديث قبيصة بن هلب عن أبيه، فإنها يفسر بعضها بعضًا، يروى عن علي : \"أن من السنة وضع اليدين تحت السرة\" لكنه حديث ضعيف عند أهل العلم ليس بصحيح، وإنما المحفوظ وضعهما على الصدر، كما في حديث وائل بن حجر، وفي حديث قبيصة بن هلب عن أبيه، وفي حديث سهل بن سعد قال: كان الرجل يؤمر أن يضع يمينه على ذراعه اليسرى في الصلاة، كانوا يؤمرون أن يضع الرجل يده اليمنى على ذراعه اليسرى في الصلاة، ففسره حديث قبيصة بن هلب عن أبيه وحديث وائل، وأن المراد: يضعهما على صدره وأطراف يده اليمنى على ساعده على ذراعه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12198/السنة-في-وضع-اليدين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53710.mp3","categories":["سنن الصلاة"]},{"id":14168,"question":"المستمع أزرق يوسف حامد بعث برسالة يقول فيها: أسألكم عن صلاة الفريضة ما هو حكم رفع اليدين في الصلاة في كل ركعة؟ جزاكم الله خيرًا.","title":"مواطن رفع اليدين في الصلاة","answer":"الجواب: السنة رفع اليدين في أربعة مواضع: عند الإحرام وعند الركوع وعند الرفع منه وعند القيام من التشهد الأول إلى الثالثة، في هذه المواضع الأربعة يستحب رفع اليدين حذاء المنكبين أو حذاء الأذنين فعله النبي ﷺ فعل هذا وهذا عليه الصلاة والسلام، عند الإحرام ترفع يديك وتقول: الله أكبر أول تكبيرة وعند الركوع ترفع يديك وتقول: الله أكبر وعند الرفع من الركوع ترفع يديك وتقول: سمع الله لمن حمده إن كنت إمامًا أو منفردًا وإن كنت مأمومًا تقول: ربنا ولك الحمد عند الرفع من الركوع رافعًا يديك، وعند القيام إلى الثالثة من التشهد الأول عند القيام من التشهد الأول إلى الثالثة ترفع يديك تقول: الله أكبر قائمًا للثالثة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12609/مواطن-رفع-اليدين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_485/48510.mp3","categories":["سنن الصلاة"]},{"id":14543,"question":"هل تجوز الصلاة بدون قراءة دعاء الاستفتاح في أول الصلاة؟","title":"حكم دعاء الاستفتاح في أول الصلاة","answer":"الجواب: الاستفتاح سنة مستحب، ولو صلى ولم يستفتح صلاته صحيحة عند جميع العلماء، الاستفتاح سنة مستحبة، والاستفتاح هو أن يقول بعد التكبيرة الأولى: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك هذا يسمى الاستفتاح، بعد التكبيرة الأولى تكبيرة الإحرام، وإن استفتح بغير هذا مما صح عن النبي ﷺ فهو حسن، مثل: اللهم باعد بيني وبين خطاياي، كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد هذا صحيح أيضًا، رواه البخاري ومسلم في الصحيحين، كان يستفتح به النبي ﷺ في الصلوات، وهناك استفتاحات أخرى صحت عنه -عليه الصلاة والسلام-. والحاصل: أنه إذا استفتح بشيء مما صح عن النبي ﷺ قبل القراءة فهو مستحب وسنة، ولو ترك ذلك فلا حرج عليه، فصلاته صحيحة.","link":"https://binbaz.org.sa/fatwas/13041/حكم-دعاء-الاستفتاح-في-اول-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48904.mp3","categories":["التكبير والاستفتاح","سنن الصلاة"]},{"id":14929,"question":"أيضًا يقول: هل هناك جلسة خفيفة في الصلاة بعد نهاية السجود الأخير في الركعة الأولى، وكذلك في الركعة الثالثة؟","title":"ما الصحيح في حكم جلسة الاستراحة؟","answer":"الجواب: نعم تسمى جلسة الاستراحة، تسمى جلسة الاستراحة، جلسة خفيفة، ليس فيها ذكر ولا دعاء، مثل جلوسه بين السجدتين، ثم ينهض إلى الثانية وإلى الرابعة لا بأس، بل هي مستحبة من سنن الصلاة على الراجح، على أرجح أقوال أهل العلم أنها سنة، يجلس قليلًا مثل جلوسه بين السجدتين، ثم ينهض إلى الثانية، ثم ينهض في الثالثة إلى الرابعة، نعم. المقدم: هل هناك جلسات غير الجلستين؟ الجواب: بس هذه، جلسة بين السجدتين معروفة، وجلوس التشهد الأول معروف، والتشهد الأخير معروف، وهذه جلسة بعد الأولى وبعد الثالثة.  بعض أهل العلم يرى أنها منسوخة، بعض أهل العلم يراها خاصة بالمريض والشيخ الكبير العاجز المحتاج، وبعض أهل العلم يراها سنة مطلقًا، وهو الصواب.","link":"https://binbaz.org.sa/fatwas/13426/ما-الصحيح-في-حكم-جلسة-الاستراحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_646/nour_64608.mp3","categories":["سنن الصلاة"]},{"id":15056,"question":"سؤاله الثالث سؤال صالح يقول: قرأت في كتاب أن النبي ﷺ في صفة صلاته أنه يجلس جلسة استراحة بعد نهوضه من السجود، وقبل القيام، فكيف تكون هذه الجلسة؛ لأنها فيما أتصور لو كانت شبيهة بجلوسه بين السجدتين لسبح المأمومون؟نرجو بسط القول فيها، أثابكم الله.","title":"صفة جلسة الاستراحة","answer":"الجواب: هذه الجلسة تسمى عند الفقهاء: جلسة الاستراحة، وهي جلسة خفيفة، كان النبي يفعلها ﷺ بعد الركعة الأولى، وقبل قيامه للثانية، وهكذا بعد الثالثة قبل قيامه للرابعة، رواها عنه مالك بن الحويرث في البخاري، ورواها عنه أيضًا أبو حميد الساعدي، والحديثان صحيحان، وهما دالان على أنها سنة، وقد جاء في حديث أبي حميد الساعدي أنه يجلس مثل جلسته فيما بين السجدتين، هذا هو الأفضل فيها، وهي جلسة خفيفة، ليس فيها ذكر، وليس فيها دعاء. وإذا كان ذلك معلومًا من النبي ﷺ فإن الصحابة لا يسبحون به؛ لأنهم يعلمون أنه يفعل ذلك، فلا يقال: إنها لو كان يفعلها مثل جلوسه بين السجدتين لسبح به، ما دام أنه يفعل ذلك وهم يعلمون أنه يفعل ذلك، فإنهم لا ينبهونه لعلمهم بأن هذا شيء يفعله -عليه الصلاة والسلام-، ويعتاده. والحاصل: أنها سنة، وليست واجبة، سنة وليست واجبة، هذا هو الصحيح، وقال بعض أهل العلم: إنها سنة في حق العاجز، كالمريض والشيخ الكبير والثقيل من أجل السمنة، ونحو ذلك.  والأرجح: أنها سنة مطلقًا، وإذا تركها بعض الأحيان فلا بأس، نعم.\nالمقدم: ولكن الهيئة هيئة الجلوس بين السجدتين...\nالشيخ: بين السجدتين هذا هو الأفضل، بين السجدتين نعم، وهذا هو الثابت في حديث أبي حميد الساعدي الأنصاري ، نعم.","link":"https://binbaz.org.sa/fatwas/13562/صفة-جلسة-الاستراحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_663/nour_66303.mp3","categories":["سنن الصلاة"]},{"id":15615,"question":"هل جلسة الاستراحة سماحة الشيخ حين الرفع من السجود الأخير إلى الركعة الثانية جائز أو غير جائز؟","title":"هل جلسة الاستراحة سُنة؟","answer":"الجواب: مستحب، على الصحيح، مستحب، جلوس قليل بعد الأولى في الثنائية والرباعية والثلاثية، وبعد الأولى والثالثة في الرباعية الظهر والعصر والعشاء؛ جلسة خفيفة كجلسته في التشهد الأول، هذا هو الأفضل، وإن لم يجلس فلا حرج، وإذا ترك بعض الأحيان فلا حرج، جلسة خفيفة بعد الأولى وبعد الثالثة من قبل أن يقوم بعد السجدة الثانية في الركعة الثالثة وفي الركعة الأولى، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14155/هل-جلسة-الاستراحة-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57103.mp3","categories":["سنن الصلاة"]},{"id":15800,"question":"أخيرًا يسأل سماحتكم فيقول: أين يكون نظر المصلي وهو في الصلاة؟","title":"موضع نظر المصلي أثناء صلاته","answer":"الجواب: السنة أن ينظر إلى موضع سجوده حال قيامه، يكون إلى موضع سجوده، وهكذا حال ركوعه، أما في حال الجلوس فينظر إلى محل إشارته، جلوسه للتشهد ينظر إلى يديه، إلى محل يديه؛ لأنه محل الإشارة، كما جاءت به السنة عن النبي -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14389/موضع-نظر-المصلي-اثناء-صلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74305.mp3","categories":["سنن الصلاة"]},{"id":16064,"question":"رسالة وصلت إلى البرنامج من المستمع سالم محمد يقول في أحد أسئلته: ألاحظ أن بعض الناس يصلون بأحذيتهم، وبعض المحدثين يقولون: إن صلاتهم باطلة، فما هو توجيهكم للطرفين؟ جزاكم الله خيرًا، وأحسن إليكم؟","title":"بعض الناس يصلون بأحذيتهم، والبعض ينكر عليهم فما توجيهكم؟","answer":"الجواب: الصلاة في الحذاء لا تبطل بها الصلاة، بل هي مستحبة، النبي ﷺ كان يصلي في نعليه -عليه الصلاة والسلام- ولما خلع الصحابة في بعض الأيام نعالهم قال: ما لكم خلعتم نعالكم؟ قالوا: رأيناك خلعت نعليك، قال: إن جبريل أتاني، فأخبرني أن بها أذى؛ فخلعتهما، فإذا أتى أحدكم المسجد؛ فلينظر في نعليه، فإن رأى فيهما أذى؛ فليمسحه، ثم ليصلي فيهما. الصلاة في النعلين ليس فيها بأس، بل هي مستحبة، والذين يقولون: لا تصح الصلاة في النعلين جهلة، لا وجه لقولهم إذا كانت النعلان طاهرتين ليس منهما بأس، ولكن تركهما إذا كانت المساجد مفروشة، والناس يتقذرون من دخوله بنعليه؛ فيجعلها عند الباب، أو في محل آخر، ويصلي حافيًا؛ حتى لا يقذر عليهم فرشهم، وحتى لا يقع بينه وبينهم شيء. أما إذا كانت المساجد لا تتأثر بذلك؛ لكونها رملية، أو بالحصباء، وهو ينظر نعليه، ويعتني بنعليه، تكون نظيفة سليمة عند دخول المسجد، فالصلاة تكون فيها أفضل. وقد جاء في الحديث عنه ﷺ أنه قال: إن اليهود لا يصلون في نعالهم، ولا في خفافهم ..... فخالفوهم لكنه في بعض الأحيان يصلي حافيًا -عليه الصلاة والسلام- فالأمر واسع، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14690/بعض-الناس-يصلون-باحذيتهم-والبعض-ينكر-عليهم-فما-توجيهكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74818.mp3","categories":["سنن الصلاة"]},{"id":16113,"question":"من المستمع (ع. ع. ر) رسالة وضمنها سؤالين، يقول في سؤاله الأول: كلمة آمين بعد قراءة الفاتحة في الصلاة هل هي واجبة، أم سنة؟ وهل إذا تركها المصلي عمدًا تبطل صلاته؟ وما الحكم فيما إذا سها عنها؟ جزاكم الله خيرًا.","title":"حكم قول: (آمين) بعد الفاتحة","answer":"الجواب: كلمة آمين سنة للإمام والمنفرد والجماعة، سنة بعد الفاتحة، وهكذا في خارج الصلاة إذا قرأ الفاتحة يقول: آمين؛ لأن فيها اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ [الفاتحة:6] دعاء، فهو يؤمن بعدها، وليست واجبة، ولو تركها فلا سجود عليه، صلاته صحيحة، وليس عليه شيء، لو تركها الإمام، أو المأمومون، أو المنفرد؛ فلا شيء عليه، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، إذًا ليس هناك تفرقة بين العمد، والسهو في هذا الموضوع؟ الشيخ: نعم السنة فعلها، هذا السنة لا يتعمد تركها، السنة فعلها، لكن لو نسيها لا شيء عليه، نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14780/حكم-قول-امين-بعد-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_803/nour_80309.mp3","categories":["سنن الصلاة"]},{"id":16115,"question":"من المستمع (ع. ع. ر) رسالة وضمنها سؤالين، يقول في سؤاله الأول: كلمة آمين بعد قراءة الفاتحة في الصلاة هل هي واجبة، أم سنة؟ وهل إذا تركها المصلي عمدًا تبطل صلاته؟ وما الحكم فيما إذا سها عنها؟ جزاكم الله خيرًا.","title":"حكم قول: (آمين) بعد الفاتحة","answer":"الجواب: كلمة آمين سنة للإمام والمنفرد والجماعة، سنة بعد الفاتحة، وهكذا في خارج الصلاة إذا قرأ الفاتحة يقول: آمين؛ لأن فيها اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ [الفاتحة:6] دعاء، فهو يؤمن بعدها، وليست واجبة، ولو تركها فلا سجود عليه، صلاته صحيحة، وليس عليه شيء، لو تركها الإمام، أو المأمومون، أو المنفرد؛ فلا شيء عليه، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، إذًا ليس هناك تفرقة بين العمد، والسهو في هذا الموضوع؟ الشيخ: نعم السنة فعلها، هذا السنة لا يتعمد تركها، السنة فعلها، لكن لو نسيها لا شيء عليه، نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14780/حكم-قول-امين-بعد-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_803/nour_80309.mp3","categories":["سنن الصلاة"]},{"id":16908,"question":"رسالة بعث بها المستمع بشير حسن عبدالله سوداني مقيم بالأفياح بقرية خصيبة فيما يبدو، الأخ يقول: إذا أردت الاستعاذة، والبسملة في الصلاة، فهل أجهر، أم تكون سرًّا؟ جزاكم الله خيرًا.","title":"حكم الإسرار بالاستعاذة والبسملة في الصلاة","answer":"الجواب: السنة سرًّا، الإمام والمنفرد، والمأموم يأتي بالاستعاذة، والتسمية سرًّا هذا هو الأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15666/حكم-الاسرار-بالاستعاذة-والبسملة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_719/nour_71915.mp3","categories":["سنن الصلاة"]},{"id":16924,"question":"يسأل ويقول: هل هناك دليل شرعي على وضع اليدين على الصدر بعد القيام من الركوع؟","title":"ما دليل وضع اليدين على الصدر بعد الركوع؟","answer":"الجواب: نعم؛ ثبت عن النبي ﷺ أنه كان يضع يده اليمنى على يده اليسرى على صدره، إذا كان قائمًا في الصلاة، وهذا عام، يعم قبل الركوع، وبعد الركوع، وهذا ثابت في السنن من حديث وائل بن حجر، قال: \"كان إذا كان قائمًا في الصلاة؛ يضع كفه اليمنى على كفه اليسرى\" وهذا يعم ما كان قبل الركوع، وبعد الركوع، وهكذا حديث سهل بن سعد عند البخاري -رحمه الله- قال: \"كان الرجل يؤمر أن يضع يده اليمنى على ذراعه اليسرى في الصلاة\" رواه البخاري، ومعنى ذلك: أنه يضع يده اليمنى على اليسرى حال وقوفه في الصلاة؛ لأن حالة الركوع يضع على ركبتيه، حالة السجود يضعها على الأرض، حالة الجلوس على فخذيه، أو ركبتيه، فما بقي إلا القيام، دل على أنه يضع يمينه على ذراعه اليسرى، وفي حديث وائل وضح أنه على صدره، فالأحاديث يفسر بعضها بعضًا. وهكذا جاء مرسلًا من حديث طاوس بن كيسان التابعي الجليل، جاء مرسلًا عنه بسندٍ صحيح: \"أن النبي ﷺ كان يضع يده اليمنى على كفه اليسرى على صدره، وهو قائم في الصلاة\" -عليه الصلاة والسلام- وهذا يشمل ما قبل الركوع، وما بعد الركوع. ومن فصل، قال: بعد الركوع لا يضع، عليه الدليل، والأصل بقاء ما كان على ما كان، فمن زعم أنه يرسلهما؛ فعليه الدليل، وإلا فالأصل بقاء وضعهما على حاله الأول، في حال القيام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15697/ما-دليل-وضع-اليدين-على-الصدر-بعد-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82612.mp3","categories":["سنن الصلاة"]},{"id":17313,"question":"في أي تكبيرة ترفع اليدان أثناء الصلاة، هل هي في تكبيرة الإحرام؟ أم أن هناك مواضع أخرى؟","title":"ما مواضع رفع اليدين في الصلاة؟","answer":"الجواب: ترفع الأيدي في أربعة مواضع: عند الإحرام، وعند الركوع وعند الرفع منه، وعند القيام من التشهد الأول، هكذا جاءت الأحاديث الصحيحة عن رسول الله -عليه الصلاة والسلام- في هذه المواضع الأربعة، يرفع يديه عند التكبيرة الأولى تكبيرة الإحرام، ويرفع يديه عند الركوع، ويرفع يديه عند الرفع من الركوع، ويرفع يديه عند القيام من التشهد الأول إلى الثالثة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16190/ما-مواضع-رفع-اليدين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83317.mp3","categories":["سنن الصلاة"]},{"id":17323,"question":"في أي تكبيرة ترفع اليدان أثناء الصلاة، هل هي في تكبيرة الإحرام؟ أم أن هناك مواضع أخرى؟","title":"ما مواضع رفع اليدين في الصلاة؟","answer":"الجواب: ترفع الأيدي في أربعة مواضع: عند الإحرام، وعند الركوع وعند الرفع منه، وعند القيام من التشهد الأول، هكذا جاءت الأحاديث الصحيحة عن رسول الله -عليه الصلاة والسلام- في هذه المواضع الأربعة، يرفع يديه عند التكبيرة الأولى تكبيرة الإحرام، ويرفع يديه عند الركوع، ويرفع يديه عند الرفع من الركوع، ويرفع يديه عند القيام من التشهد الأول إلى الثالثة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16190/ما-مواضع-رفع-اليدين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83317.mp3","categories":["سنن الصلاة"]},{"id":17571,"question":"بعد هذا ننتقل إلى رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: محمد حمد عيظة النجراني، من مكة المكرمة، الأخ محمد له جمعٌ من الأسئلة، في أحدها يقول: ما تقولون -جزاكم الله خيرًا- في ضم اليدين عند قول: سمع الله لمن حمده؟","title":"حكم ضم اليدين عند الرفع من الركوع","answer":"الجواب: السنة أن يرفع يديه غير مضمومتين، إلى منكبيه، أو إلى أذنيه، كما فعل النبي ﷺ، فرفع اليدين سنة عند الإحرام، وعند الركوع، وعند الرفع منه، وعند القيام من التشهد الأول إلى الثالثة، يرفعهما إلى منكبيه، أو إلى فروع أذنيه، كل واحدة تحاذي.. اليمين تحاذي المنكب الأيمن، أو الأذن اليمنى، واليسرى باليسرى، هذا هو السنة، رفع اليدين مع قوله: سمع الله لمن حمده، والمأموم مع قوله: ربنا ولك الحمد، عند رفعه من الركوع، كما يرفعهما عند الركوع، وعند الإحرام، عند التكبيرة الأولى، وعند القيام من التشهد الأول، كان النبي ﷺ يفعل هذا تارةً إلى منكبيه، وتارةً يرفعهما ﷺ إلى فروع أذنيه، عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16494/حكم-ضم-اليدين-عند-الرفع-من-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_726/nour_72606.mp3","categories":["سنن الصلاة"]},{"id":17609,"question":"أيضًا يسأل يقول: لدينا مسألة خلافية في القبض والإرسال في الصلاة، هناك أدلة على القبض كثيرة نرجو منكم توضيحًا لهذه المسألة؟","title":"ما حكم ضم اليدين في الصلاة؟","answer":"الجواب: السنة في الصلاة القبض حال القيام، يضع يده اليمنى -كفه اليمنى- على كفه اليسرى هذا هو القبض على صدره؛ لأنه ثبت عن النبي ﷺ من حديث وائل بن حجر \"أنه كان يضع يمينه على شماله.. كفه اليمنى على كفه اليسرى على صدره\" وثبت أيضًا من حديث قبيصة بن هلب الطائي عن أبيه بمعنى ذلك، وفي صحيح البخاري رحمه الله عن سهل بن سعد قال: \"كان الرجل يؤمر أن يضع يده اليمنى على ذراعه اليسرى في الصلاة\"، ومعنى \"في الصلاة\" يعني: حال القيام، كما فسره حديث وائل وحديث قبيصة بن هلب لأن الصلاة لها أحوال:\nفي الركوع يضع يديه على ركبتيه مفردتي الأصابع، هذا السنة.\nفي السجود يضعهما على الأرض حيال منكبيه أو حيال أذنينه.\nفي الجلوس يضعهما على فخذيه أو ركبتيه.\nفما بقي إلا حال القيام، في حال القيام يضعها على صدره ويكون أطرافها على ذراعه الأيسر، أطراف يده اليمنى -كفه اليمنى- على ذراعه الأيسر كما في حديث سهل، وفي السنة أيضًا من حديث طاوس بن كيسان اليماني التابعي الجليل ما يوافق ذلك عن النبي ﷺ: \"أنه كان يضع يده اليمنى على كفه اليسرى على صدره في الصلاة\"، وهذا مرسل جيد يوافق الأحاديث الصحيحة المتصلة المرفوعة.\nأما إرسالها على الجنبين كما يفعله بعض الناس فليس عليه دليل، وإن ذهب إليه بعض المالكية لكن هذا ليس عليه.. الأفضل تركه، الأفضل تركه والأخذ بما دلت عليه الأحاديث الصحيحة.\nولكن لا ينبغي النزاع في هذا والاختلاف والعداوة والشحناء، ينبغي التساهل في هذا والتسامح؛ لأنها سنة لو أرخى يديه صحت صلاته، أو ضمها صحت صلاته إنما الخلاف في الأفضل والسنة، وكثير من إخواننا في أفريقيا يحصل بينهم شحناء بسبب هذا ولا ينبغي ذلك، ينبغي في مثل هذا التسامح والدعوة إلى الخير بالرفق وينصح إخوانه أن يضعوا أيديهم على صدورهم من دون شدة ولا منازعة ولا هجر وليبين السنة ويدعو إليها بحلم وصبر ورفق. وعلى من دعي إلى السنة أن يستجيب ولا يجوز التقليد، التقليد ما يجوز تقلد زيد ولا عمرو في خلاف السنة ولو كان عظيمًا ولو كان مالكًا أو كان أبا حنيفة أو الشافعي أو أحمد لا. طالب العلم لا يقلد العلماء يأخذ بالدليل، إذا خفي عليه الدليل تبع أهل العلم المعروفين بالسنة والاستقامة، لكن إذا قام الدليل عن الرسول ﷺ فالواجب والمشروع اتباع من معه الدليل، سنة في السنة وواجبًا في الواجبات، الله يقول: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59]، ويقول سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّه [الشورى:10]، ويقول جل وعلا: أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ [النساء:59] ، ويقول جل وعلا: مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ [النساء:80].\nفأنت مأمور بطاعة الرسول ﷺ إذا عرفت السنة والسنة واضحة في هذا أن تضع يدك اليمنى -كفك اليمنى- على الكف اليسرى في الصلاة وأنت قائم قبل الركوع وبعده، قبل الركوع وهكذا بعد الركوع إذا قمت وأنت واقف بعد الركوع تضع كفك اليمنى على كفك اليسرى على الصدر هذا هو الأفضل. وقال جماعة من العلماء: على السرة، وقال بعضهم: تحت السرة، ولكن ليس عليه دليل صحيح، والحديث الذي يروى عن علي في وضعهما تحت السرة ضعيف، والمحفوظ وضعها على الصدر.. وضع اليدين على الصدر، هذا هو المحفوظ من حديث وائل ومن حديث قبيصة بن هلب الطائي عن أبيه ومن مرسل طاوس ويؤيده ما رواه البخاري في الصحيح من حديث أبي حازم عن سهل بن سعد كما تقدم.\nفنصيحتي لإخواني أن يأخذوا بهذه السنة من دون شدة على الآخرين مع الرفق والحكمة والتواصي بالسنة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16539/ما-حكم-ضم-اليدين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_842/nour_84202.mp3","categories":["سنن الصلاة"]},{"id":17617,"question":"أيضًا يسأل يقول: لدينا مسألة خلافية في القبض والإرسال في الصلاة، هناك أدلة على القبض كثيرة نرجو منكم توضيحًا لهذه المسألة؟","title":"ما حكم ضم اليدين في الصلاة؟","answer":"الجواب: السنة في الصلاة القبض حال القيام، يضع يده اليمنى -كفه اليمنى- على كفه اليسرى هذا هو القبض على صدره؛ لأنه ثبت عن النبي ﷺ من حديث وائل بن حجر \"أنه كان يضع يمينه على شماله.. كفه اليمنى على كفه اليسرى على صدره\" وثبت أيضًا من حديث قبيصة بن هلب الطائي عن أبيه بمعنى ذلك، وفي صحيح البخاري رحمه الله عن سهل بن سعد قال: \"كان الرجل يؤمر أن يضع يده اليمنى على ذراعه اليسرى في الصلاة\"، ومعنى \"في الصلاة\" يعني: حال القيام، كما فسره حديث وائل وحديث قبيصة بن هلب لأن الصلاة لها أحوال:\nفي الركوع يضع يديه على ركبتيه مفردتي الأصابع، هذا السنة.\nفي السجود يضعهما على الأرض حيال منكبيه أو حيال أذنينه.\nفي الجلوس يضعهما على فخذيه أو ركبتيه.\nفما بقي إلا حال القيام، في حال القيام يضعها على صدره ويكون أطرافها على ذراعه الأيسر، أطراف يده اليمنى -كفه اليمنى- على ذراعه الأيسر كما في حديث سهل، وفي السنة أيضًا من حديث طاوس بن كيسان اليماني التابعي الجليل ما يوافق ذلك عن النبي ﷺ: \"أنه كان يضع يده اليمنى على كفه اليسرى على صدره في الصلاة\"، وهذا مرسل جيد يوافق الأحاديث الصحيحة المتصلة المرفوعة.\nأما إرسالها على الجنبين كما يفعله بعض الناس فليس عليه دليل، وإن ذهب إليه بعض المالكية لكن هذا ليس عليه.. الأفضل تركه، الأفضل تركه والأخذ بما دلت عليه الأحاديث الصحيحة.\nولكن لا ينبغي النزاع في هذا والاختلاف والعداوة والشحناء، ينبغي التساهل في هذا والتسامح؛ لأنها سنة لو أرخى يديه صحت صلاته، أو ضمها صحت صلاته إنما الخلاف في الأفضل والسنة، وكثير من إخواننا في أفريقيا يحصل بينهم شحناء بسبب هذا ولا ينبغي ذلك، ينبغي في مثل هذا التسامح والدعوة إلى الخير بالرفق وينصح إخوانه أن يضعوا أيديهم على صدورهم من دون شدة ولا منازعة ولا هجر وليبين السنة ويدعو إليها بحلم وصبر ورفق. وعلى من دعي إلى السنة أن يستجيب ولا يجوز التقليد، التقليد ما يجوز تقلد زيد ولا عمرو في خلاف السنة ولو كان عظيمًا ولو كان مالكًا أو كان أبا حنيفة أو الشافعي أو أحمد لا. طالب العلم لا يقلد العلماء يأخذ بالدليل، إذا خفي عليه الدليل تبع أهل العلم المعروفين بالسنة والاستقامة، لكن إذا قام الدليل عن الرسول ﷺ فالواجب والمشروع اتباع من معه الدليل، سنة في السنة وواجبًا في الواجبات، الله يقول: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59]، ويقول سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّه [الشورى:10]، ويقول جل وعلا: أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ [النساء:59] ، ويقول جل وعلا: مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ [النساء:80].\nفأنت مأمور بطاعة الرسول ﷺ إذا عرفت السنة والسنة واضحة في هذا أن تضع يدك اليمنى -كفك اليمنى- على الكف اليسرى في الصلاة وأنت قائم قبل الركوع وبعده، قبل الركوع وهكذا بعد الركوع إذا قمت وأنت واقف بعد الركوع تضع كفك اليمنى على كفك اليسرى على الصدر هذا هو الأفضل. وقال جماعة من العلماء: على السرة، وقال بعضهم: تحت السرة، ولكن ليس عليه دليل صحيح، والحديث الذي يروى عن علي في وضعهما تحت السرة ضعيف، والمحفوظ وضعها على الصدر.. وضع اليدين على الصدر، هذا هو المحفوظ من حديث وائل ومن حديث قبيصة بن هلب الطائي عن أبيه ومن مرسل طاوس ويؤيده ما رواه البخاري في الصحيح من حديث أبي حازم عن سهل بن سعد كما تقدم.\nفنصيحتي لإخواني أن يأخذوا بهذه السنة من دون شدة على الآخرين مع الرفق والحكمة والتواصي بالسنة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16539/ما-حكم-ضم-اليدين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_842/nour_84202.mp3","categories":["سنن الصلاة"]},{"id":17639,"question":"ما تقولون في الاستراحة القصيرة، عند النهوض من أول السجدة، عند أول ركعة؟ وثالث ركعة في الرباعية والثلاثية؟ جزاكم الله خيرًا.","title":"ما حكم جلسة الاستراحة؟","answer":"الجواب: هذه يقال لها: جلسة الاستراحة، واختلف العلماء في ...........، منهم من قال: إنها تفعل عند الحاجة، كالمرض، وكبر السن، ومنهم من قال: إنها سنة من فعل النبي ﷺ، سنة مطلقًا، وهذا هو الأرجح، أنها مستحبة، مطلقًا، بعد الأولى من جميع الصلوات، وبعد الثالثة من الرباعية، قليلًا بعد السجدة الثانية، بعد الأولى، والثالثة، إذا نهض من السجدة الثانية، جلس قليلًا، كجلوسه بين السجدتين، ثم ينهض، هذه مستحبة، ومن تركها فلا حرج.\nالمقدم: جزاكم الله خيرًا، متى يقول: الله أكبر، عند السجدة الأخيرة، إذا كان إمامًا؟ هل هو عندما يرفع رأسه من السجود؟ أو عندما يقوم من الاستراحة القصيرة، إذا صحت عندكم؟ حيث أنه إذا كبر عندما يرفع رأسه من السجدة ويقعد، فسيقوم المأمومين على طول، أفيدونا جزاكم الله خيرًا؟\nالشيخ: الأقرب والله أعلم، أنه يفعل ذلك عند قيامه من الجلسة، إذا قام من الجلسة؛ كبر حتى يقوم الناس بعده، وحتى لا يسابقوه، يجلس قليلًا، ثم ينهض مكبرًا. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16560/ما-حكم-جلسة-الاستراحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_726/nour_72607.mp3","categories":["سنن الصلاة"]},{"id":17864,"question":"حدثوني عن وضع اليدين أثناء القيام أين أضعهما؟","title":"أين توضع اليدان أثناء القيام في الصلاة؟","answer":"الجواب: السنة وضعهما على الصدر؛ لأنه ثبت عن النبي ﷺ من حديث وائل، ومن حديث قبيصة هلب الطائي عن أبيه \"أنه كان يضعهما على صدره عليه الصلاة والسلام\"، وثبت مرسلًا من طريق طاوس بن كيسان التابعي الجليل عن النبي ﷺ وهو يؤيد المرفوع.\nوبعض أهل العلم يرى وضعها على السرة، وبعض أهل العلم يرى وضعهما تحت السرة، والحديث في هذا ضعيف -تحت السرة- والأفضل فوق الصدر هذا هو الأفضل؛ لأن الأحاديث فيها أصح، الأحاديث في ذلك أصح، والأمر في هذا واسع، كله سنة، لو سدلهما صحت صلاته، لو أرسلهما كما قال بعض أهل العلم صحت صلاته، ولكن السنة أن يضمهما إلى صدره ولا يرسلهما، هذا هو السنة، ولا ينبغي في هذا النزاع والخلاف والجدل والفرقة، بل ينبغي في هذا التسامح والتيسير؛ لأن الاجتماع والتعاون على الخير أمر مطلوب. والذي يجعلها تحت السرة تأول قول بعض أهل العلم وبعض الأحاديث الضعيفة فلا ينبغي التشنيع والتشديد في هذا المقام، ينبغي الرفق والحكمة في هذا والنصيحة بدون فرقة ولا اختلاف ولا تشنيع، ولكن الأفضل للمؤمن أن يتحرى ما هو الأثبت وما هو الأقرب إلى الصواب في مسائل الخلاف. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16879/اين-توضع-اليدان-اثناء-القيام-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_845/nour_84505.mp3","categories":["سنن الصلاة"]},{"id":17869,"question":"مع أي التكبيرات أرفع اليدين؟","title":"ما مواضع رفع اليدين في تكبيرات الصلاة؟","answer":"الجواب: السنة أن ترفع اليدين في التكبيرة الأولى حيال منكبيك أو حيال أذنيك في التكبيرة الأولى وهي تكبيرة الإحرام، وعند الركوع أيضًا، وعند الرفع منه، وعند القيام من التشهد الأول للثالثة، في هذه المواضع الأربعة السنة رفع اليدين للرجل والمرأة جميعًا، حيال المنكبين أو حيال الأذنين، تارة كذا وتارة كذا كله ثبت عن النبي ﷺ. نعم.","link":"https://binbaz.org.sa/fatwas/16876/ما-مواضع-رفع-اليدين-في-تكبيرات-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_845/nour_84503.mp3","categories":["سنن الصلاة"]},{"id":17874,"question":"حدثوني عن وضع اليدين أثناء القيام أين أضعهما؟","title":"أين توضع اليدان أثناء القيام في الصلاة؟","answer":"الجواب: السنة وضعهما على الصدر؛ لأنه ثبت عن النبي ﷺ من حديث وائل، ومن حديث قبيصة هلب الطائي عن أبيه \"أنه كان يضعهما على صدره عليه الصلاة والسلام\"، وثبت مرسلًا من طريق طاوس بن كيسان التابعي الجليل عن النبي ﷺ وهو يؤيد المرفوع.\nوبعض أهل العلم يرى وضعها على السرة، وبعض أهل العلم يرى وضعهما تحت السرة، والحديث في هذا ضعيف -تحت السرة- والأفضل فوق الصدر هذا هو الأفضل؛ لأن الأحاديث فيها أصح، الأحاديث في ذلك أصح، والأمر في هذا واسع، كله سنة، لو سدلهما صحت صلاته، لو أرسلهما كما قال بعض أهل العلم صحت صلاته، ولكن السنة أن يضمهما إلى صدره ولا يرسلهما، هذا هو السنة، ولا ينبغي في هذا النزاع والخلاف والجدل والفرقة، بل ينبغي في هذا التسامح والتيسير؛ لأن الاجتماع والتعاون على الخير أمر مطلوب. والذي يجعلها تحت السرة تأول قول بعض أهل العلم وبعض الأحاديث الضعيفة فلا ينبغي التشنيع والتشديد في هذا المقام، ينبغي الرفق والحكمة في هذا والنصيحة بدون فرقة ولا اختلاف ولا تشنيع، ولكن الأفضل للمؤمن أن يتحرى ما هو الأثبت وما هو الأقرب إلى الصواب في مسائل الخلاف. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16879/اين-توضع-اليدان-اثناء-القيام-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_845/nour_84505.mp3","categories":["سنن الصلاة"]},{"id":18276,"question":"يسأل أخونا أيضًا ويقول: أعتقد أنني سمعت في برنامج نور على الدرب، ولكن لا أتذكر جيدًا أن الجلوس بعد الركعة الأولى والثالثة يعتبر زيادة تستوجب سجودًا بعدي.رأيت صديقًا لي قام بذلك فنبهته، وقلت: إن ذلك زيادة، لكنه أصر على أن ذلك وارد عن الرسول ﷺ وأنه كان يجلس مطمئنًا قبل الوقوف للركعة التالية، ولكني لم أر دليلًا قدمه لي، فأي الأمرين صحيحًا؟ جزاكم الله خيرًا.","title":"هل جلسة الاستراحة سنة؟","answer":"الجواب: هذه الجلسة يقال لها: جلسة الاستراحة، وهي: جلسة خفيفة قليلة بعد الأولى في الصلوات الخمس، وبعد الثالثة في الرباعية، كان النبي ﷺ يجلسها كجلسته بين السجدتين، ثبت ذلك في حديث مالك بن الحويرث عند البخاري، وثبت ذلك في السنن من حديث أبي حميد الساعدي، فهي مستحبة على الصحيح، وهي جلسة خفيفة بعدما يرفع من السجدة الثانية في الركعة الأولى من جميع الصلوات، وفي الركعة الثالثة في الرباعية قبل أن ينهض إلى الرابعة. وذهب بعض أهل العلم إلى أنها تختص بمن كان كبير السن، أو مريضًا أو ثقيلًا يشق عليه النهوض، ولكن هذا ليس بجيد.. والصواب: أنه سنة مطلقًا لفعل النبي ﷺ هذا هو الصواب، فإذا جلسها لتحري السنة فليس عليه سجود سهو، ولا تسمى زيادة مخالفة للشرع، بل هي زيادة شرعية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17325/هل-جلسة-الاستراحة-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91012.mp3","categories":["سنن الصلاة"]},{"id":18815,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول: أختكم في الله مها عبد العزيز، أختنا تسأل في سؤالها عن يدي المرأة أين تضعهما أثناء الصلاة؟","title":"أين تضع المرأة يديها أثناء القيام في الصلاة؟","answer":"الجواب: كالرجل السنة أن تضعهما على صدرها، كما جاء في السنة؛ لأن الأصل أن الرجال والنساء سواء في الصلاة، إلا ما خصه الدليل، فهي تعمل كما يعمل الرجل في صلاتها، تكبر وتقرأ الاستفتاح، وتقرأ الفاتحة، وما تيسر معها، تركع وتطمئن ترفع وتعتدل وتطمئن، وتضع يديها وقت القيام على صدرها، قبل الركوع وبعده، كالرجل سواء، نعم. لأن الرسول  قال: صلوا كما رأيتموني أصلي وهذا يعم الرجال والنساء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17945/اين-تضع-المراة-يديها-اثناء-القيام-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_921/nour_92105.mp3","categories":["سنن الصلاة"]}]
